import json
import sys

import framework_evidence


def main():
    argv = [
        "nmap",
        "-n",
        "-sT",
        "-sV",
        "-p-",
        "--reason",
        "192.168.2.0/24",
    ]
    try:
        result = framework_evidence.run_tool(argv)
        if isinstance(result, str):
            print(result)
        else:
            print(json.dumps(result, ensure_ascii=False, default=str))
    except Exception as exc:
        print(json.dumps({
            "tool": "nmap",
            "argv": argv,
            "execution_error": str(exc),
            "coverage": "No scan results available; host and service state remain unknown.",
        }, ensure_ascii=False))
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

