import html.parser
import json
import re
import urllib.error
import urllib.parse
import urllib.request

HOST = "192.168.2.4"
BASE = "http://192.168.2.4:80"
MAX_URLS = 40
BODY_LIMIT = 20000
TIMEOUT = 8


def origin(url):
    p = urllib.parse.urlsplit(url)
    return p.scheme.lower(), (p.hostname or "").lower(), p.port or (80 if p.scheme == "http" else 443)


TARGET_ORIGIN = origin(BASE)


def normalize_url(url, base=BASE):
    absolute = urllib.parse.urljoin(base, url)
    p = urllib.parse.urlsplit(absolute)
    if origin(absolute) != TARGET_ORIGIN or p.username or p.password:
        return None
    # Fragments are client-side only. Avoid query-bearing links because GET query
    # endpoints can have side effects and are unnecessary for public page discovery.
    if p.query:
        return None
    path = p.path or "/"
    return urllib.parse.urlunsplit(("http", HOST, path, "", ""))


class PageParser(html.parser.HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links = []
        self.forms = []
        self._form = None

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag.lower() in ("a", "area", "link") and attrs.get("href"):
            self.links.append(attrs["href"])
        if tag.lower() == "form":
            self._form = {
                "action": attrs.get("action", ""),
                "method": attrs.get("method", "get").upper(),
                "fields": [],
            }
            self.forms.append(self._form)
        elif self._form is not None and tag.lower() in ("input", "button", "select", "textarea"):
            self._form["fields"].append({
                "tag": tag.lower(),
                "type": attrs.get("type", ""),
                "name": attrs.get("name", ""),
                "autocomplete": attrs.get("autocomplete", ""),
            })

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self._form = None


def safe_headers(headers):
    result = {}
    for key, value in headers.items():
        if key.lower() in ("set-cookie", "www-authenticate"):
            # Preserve whether such a header was present without emitting cookie
            # values or challenge details that may contain sensitive material.
            result[key] = "[redacted; header present]"
        else:
            result[key] = value
    return result


class SameOriginRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        candidate = normalize_url(newurl, req.full_url)
        if candidate is None:
            return None
        return super().redirect_request(req, fp, code, msg, headers, candidate)


opener = urllib.request.build_opener(SameOriginRedirect())
seed_paths = [
    "/", "/robots.txt", "/sitemap.xml",
    "/admin", "/admin/", "/admin/login", "/login", "/user/login",
    "/administrator/", "/wp-login.php", "/phpmyadmin/", "/dashboard/",
]
queue = []
for path in seed_paths:
    url = normalize_url(path)
    if url and url not in queue:
        queue.append(url)
seen = set()
records = []
discovered_routes = set()

while queue and len(seen) < MAX_URLS:
    url = queue.pop(0)
    if url in seen:
        continue
    seen.add(url)
    record = {"requested_url": url, "method": "GET"}
    try:
        request = urllib.request.Request(
            url,
            headers={"User-Agent": "PublicPageInspector/1.0", "Accept": "text/html,text/plain,application/xml,*/*"},
            method="GET",
        )
        try:
            response = opener.open(request, timeout=TIMEOUT)
        except urllib.error.HTTPError as exc:
            # HTTP error responses are still useful observations (for example 401/404).
            response = exc
        with response:
            raw = response.read(BODY_LIMIT + 1)
            truncated = len(raw) > BODY_LIMIT
            raw = raw[:BODY_LIMIT]
            charset = response.headers.get_content_charset() or "utf-8"
            try:
                body = raw.decode(charset, errors="replace")
            except LookupError:
                body = raw.decode("utf-8", errors="replace")
            record.update({
                "status": getattr(response, "status", response.getcode()),
                "final_url": response.geturl(),
                "headers": safe_headers(response.headers),
                "body_bytes_captured": len(raw),
                "body_truncated": truncated,
                "body": body,
            })

        parser = PageParser()
        try:
            parser.feed(body)
            parser.close()
            record["forms"] = parser.forms
            record["links_found"] = len(parser.links)
            candidates = list(parser.links)
        except Exception as exc:
            record["html_parse_error"] = repr(exc)
            candidates = []

        # Extract sitemap locations and robots.txt directives from captured text.
        candidates.extend(re.findall(r"<loc>\s*(.*?)\s*</loc>", body, flags=re.I | re.S))
        if urllib.parse.urlsplit(url).path.lower() == "/robots.txt":
            for line in body.splitlines():
                match = re.match(r"\s*(?:Disallow|Sitemap)\s*:\s*(\S+)", line, re.I)
                if match:
                    candidates.append(match.group(1))

        for item in candidates:
            candidate = normalize_url(item, record.get("final_url", url))
            if candidate:
                discovered_routes.add(urllib.parse.urlsplit(candidate).path)
                path_lower = urllib.parse.urlsplit(candidate).path.lower()
                # Do not follow likely logout or destructive/action routes.
                if not re.search(r"(?:logout|log-out|signout|delete|remove|reset)", path_lower):
                    if candidate not in seen and candidate not in queue and len(seen) + len(queue) < MAX_URLS:
                        queue.append(candidate)
    except (urllib.error.URLError, TimeoutError, OSError, ValueError) as exc:
        record["error"] = repr(exc)
    except Exception as exc:
        record["error"] = "unexpected: " + repr(exc)
    records.append(record)

print(json.dumps({
    "target": BASE,
    "scope": "HTTP on 192.168.2.4:80; same-origin requests only",
    "method": "GET only; no forms submitted and no credentials attempted",
    "limits": {
        "max_unique_urls": MAX_URLS,
        "max_body_bytes_per_response": BODY_LIMIT,
        "timeout_seconds_per_request": TIMEOUT,
        "set_cookie_and_www_authenticate_values": "redacted",
        "query_string_links": "not followed",
    },
    "requests_completed_or_attempted": len(records),
    "url_cap_reached_with_more_queued": bool(queue) and len(seen) >= MAX_URLS,
    "discovered_same_origin_routes": sorted(discovered_routes),
    "records": records,
}, ensure_ascii=False))

