import http.client
import json
import urllib.parse
from html.parser import HTMLParser

HOST = "192.168.2.4"
PORT = 80
ORIGIN = f"http://{HOST}:{PORT}"
BODY_LIMIT = 65536
TIMEOUT = 8


class LinkParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links = []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        for name in ("href", "src"):
            value = attrs.get(name)
            if value:
                self.links.append(value)
        if tag.lower() == "form":
            action = attrs.get("action")
            if action:
                self.links.append(action)


def same_origin_url(reference, base_url):
    absolute = urllib.parse.urljoin(base_url, reference)
    parts = urllib.parse.urlsplit(absolute)
    if parts.scheme.lower() != "http" or parts.hostname != HOST:
        return None
    try:
        effective_port = parts.port or 80
    except ValueError:
        return None
    if effective_port != PORT or parts.username is not None or parts.password is not None:
        return None
    path = parts.path or "/"
    return urllib.parse.urlunsplit(("http", f"{HOST}:{PORT}", path, parts.query, ""))


def request_get(url):
    parts = urllib.parse.urlsplit(url)
    target = parts.path or "/"
    if parts.query:
        target += "?" + parts.query
    conn = http.client.HTTPConnection(HOST, PORT, timeout=TIMEOUT)
    try:
        conn.request("GET", target, headers={"Host": HOST, "User-Agent": "public-resource-evidence-check/1.0", "Connection": "close"})
        response = conn.getresponse()
        raw = response.read(BODY_LIMIT + 1)
        truncated = len(raw) > BODY_LIMIT
        if truncated:
            raw = raw[:BODY_LIMIT]
        headers = {key: value for key, value in response.getheaders()}
        charset = "utf-8"
        content_type = headers.get("Content-Type", "")
        for part in content_type.split(";")[1:]:
            if "charset=" in part.lower():
                charset = part.split("=", 1)[1].strip().strip('"')
                break
        try:
            body = raw.decode(charset, errors="replace")
        except LookupError:
            body = raw.decode("utf-8", errors="replace")
        return {"requested_url": url, "method": "GET", "status": response.status,
                "reason": response.reason, "headers": headers,
                "body_bytes_captured": len(raw), "body_truncated": truncated,
                "body": body}
    except Exception as exc:
        return {"requested_url": url, "method": "GET", "error": f"{type(exc).__name__}: {exc}"}
    finally:
        conn.close()


def extract_links(record):
    if "body" not in record:
        return []
    parser = LinkParser()
    try:
        parser.feed(record["body"])
    except Exception:
        pass
    links = []
    for reference in parser.links:
        url = same_origin_url(reference, record["requested_url"])
        if url and url not in links:
            links.append(url)
    return links


def main():
    # These entry points are based on the observed application route and public root.
    initial = [f"{ORIGIN}/", f"{ORIGIN}/login.php"]
    metadata = [
        f"{ORIGIN}/robots.txt",
        f"{ORIGIN}/sitemap.xml",
        f"{ORIGIN}/security.txt",
        f"{ORIGIN}/.well-known/security.txt",
    ]
    records = []
    seen = set()
    discovered_direct_links = []

    # Fetch observed application pages, then their direct same-origin links, including
    # query strings. Do not recursively crawl pages or follow redirects automatically.
    first_records = []
    for url in initial:
        if url in seen:
            continue
        seen.add(url)
        record = request_get(url)
        records.append(record)
        first_records.append(record)
    for record in first_records:
        for url in extract_links(record):
            if url not in seen:
                seen.add(url)
                discovered_direct_links.append(url)
    for url in discovered_direct_links + metadata:
        if url in seen:
            continue
        seen.add(url)
        records.append(request_get(url))

    print(json.dumps({
        "target_origin": ORIGIN,
        "scope": "Public same-origin HTTP resources only",
        "request_policy": "GET only; no form submissions, credentials, or automatic redirects",
        "initial_resources": initial,
        "direct_same_origin_links_discovered": discovered_direct_links,
        "public_metadata_paths_checked": metadata,
        "unique_urls_requested": len(records),
        "body_limit_bytes_per_response": BODY_LIMIT,
        "timeout_seconds_per_request": TIMEOUT,
        "records": records,
        "limitations": "Only direct links from the two initial pages were followed. Cross-origin links and redirects were not followed; bodies exceeding the per-response capture limit are marked truncated. HTTP errors and unavailable resources are recorded as observations, not proof that other paths are unavailable."
    }, ensure_ascii=False))


if __name__ == "__main__":
    main()

