import html
import json
import urllib.error
import urllib.parse
import urllib.request
from html.parser import HTMLParser

LOGIN_URL = "http://192.168.2.4/login.php"
USERNAME = "student"
PASSWORD = "student"
BODY_LIMIT = 65536
REDIRECT_LIMIT = 10


class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


class PageParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.forms = []
        self.current_form = None
        self.links = []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag.lower() == "form":
            self.current_form = {"attrs": attrs, "inputs": []}
            self.forms.append(self.current_form)
        elif tag.lower() == "input" and self.current_form is not None:
            self.current_form["inputs"].append(attrs)
        elif tag.lower() == "a" and attrs.get("href"):
            self.links.append(attrs["href"])

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self.current_form = None


def origin(url):
    p = urllib.parse.urlsplit(url)
    return p.scheme.lower(), (p.hostname or "").lower(), p.port or (443 if p.scheme.lower() == "https" else 80)


def response_record(url, method, data=None):
    req = urllib.request.Request(url, data=data, method=method)
    try:
        response = opener.open(req, timeout=8)
    except urllib.error.HTTPError as exc:
        response = exc
    except Exception as exc:
        return None, {"requested_url": url, "method": method, "error": type(exc).__name__ + ": " + str(exc)}

    try:
        raw = response.read(BODY_LIMIT + 1)
        truncated = len(raw) > BODY_LIMIT
        raw = raw[:BODY_LIMIT]
        charset = response.headers.get_content_charset() or "utf-8"
        try:
            body = raw.decode(charset, errors="replace")
        except LookupError:
            body = raw.decode("utf-8", errors="replace")
        record = {
            "requested_url": url,
            "method": method,
            "status": getattr(response, "status", None),
            "reason": getattr(response, "reason", ""),
            "headers": dict(response.headers.items()),
            "body_bytes_captured": len(raw),
            "body_truncated": truncated,
            "body": body,
        }
        return response.headers, record
    finally:
        response.close()


def request_with_same_origin_redirects(url, method, data=None):
    records = []
    current_url, current_method, current_data = url, method, data
    for _ in range(REDIRECT_LIMIT + 1):
        headers, record = response_record(current_url, current_method, current_data)
        records.append(record)
        if headers is None:
            return records, None
        status = record.get("status")
        location = headers.get("Location")
        if status not in (301, 302, 303, 307, 308) or not location:
            return records, record
        next_url = urllib.parse.urljoin(current_url, location)
        if origin(next_url) != origin(LOGIN_URL):
            record["redirect_not_followed"] = "redirect target is not same-origin"
            record["redirect_target"] = next_url
            return records, record
        if len(records) > REDIRECT_LIMIT:
            record["redirect_not_followed"] = "redirect limit reached"
            return records, record
        if status == 303 or (status in (301, 302) and current_method == "POST"):
            current_method, current_data = "GET", None
        current_url = next_url
    return records, records[-1] if records else None


cookie_jar = urllib.request.CookieJar()
opener = urllib.request.build_opener(NoRedirect(), urllib.request.HTTPCookieProcessor(cookie_jar))
output = {
    "target_origin": "http://192.168.2.4:80",
    "credential_source": "Credentials disclosed on the observed public home page",
    "credentials_submitted": {"username": USERNAME, "password": "[redacted]"},
    "requests": [],
    "authenticated_response_direct_links": [],
    "limitations": [],
}

# Load the observed form and obtain its session cookie before submitting credentials.
get_records, get_result = request_with_same_origin_redirects(LOGIN_URL, "GET")
output["requests"].extend(get_records)
if not get_result or "body" not in get_result:
    output["limitations"].append("Could not retrieve the login form; credentials were not submitted.")
else:
    parser = PageParser()
    parser.feed(get_result["body"])
    chosen = None
    for form in parser.forms:
        names = {field.get("name", "") for field in form["inputs"]}
        if "username" in names and "password" in names:
            chosen = form
            break

    if chosen is None:
        output["limitations"].append("No form containing username and password inputs was found; credentials were not submitted.")
    else:
        attrs = chosen["attrs"]
        method = attrs.get("method", "get").lower()
        action = urllib.parse.urljoin(get_result.get("requested_url", LOGIN_URL), attrs.get("action", ""))
        if origin(action) != origin(LOGIN_URL):
            output["limitations"].append("The observed form action is not same-origin; credentials were not submitted.")
        elif method != "post":
            output["limitations"].append("The observed login form does not use POST; credentials were not submitted.")
        else:
            fields = {}
            for field in chosen["inputs"]:
                name = field.get("name")
                if not name:
                    continue
                field_type = field.get("type", "text").lower()
                if field_type == "hidden":
                    fields[name] = field.get("value", "")
            fields["username"] = USERNAME
            fields["password"] = PASSWORD
            body = urllib.parse.urlencode(fields).encode("utf-8")
            post_records, post_result = request_with_same_origin_redirects(action, "POST", body)
            output["requests"].extend(post_records)

            if post_result and "body" in post_result:
                # Examine direct same-origin anchors in the final application response.
                result_parser = PageParser()
                result_parser.feed(post_result["body"])
                seen = set()
                for href in result_parser.links:
                    linked = urllib.parse.urljoin(post_result.get("requested_url", action), html.unescape(href))
                    parts = urllib.parse.urlsplit(linked)
                    linked = urllib.parse.urlunsplit((parts.scheme, parts.netloc, parts.path, parts.query, ""))
                    if origin(linked) != origin(LOGIN_URL) or linked in seen:
                        continue
                    seen.add(linked)
                    output["authenticated_response_direct_links"].append(linked)
                    page_records, _ = request_with_same_origin_redirects(linked, "GET")
                    output["requests"].extend(page_records)
            else:
                output["limitations"].append("Login submission produced no response body to inspect for directly linked pages.")

print(json.dumps(output, ensure_ascii=False))

