import http.cookiejar
import json
import urllib.error
import urllib.parse
import urllib.request
from html.parser import HTMLParser

BASE = "http://192.168.2.4:80"
LOGIN_URL = BASE + "/login.php"
BODY_LIMIT = 65536
TIMEOUT = 8


def origin(url):
    p = urllib.parse.urlsplit(url)
    port = p.port or (80 if p.scheme == "http" else 443)
    return p.scheme.lower(), (p.hostname or "").lower(), port


class SameOriginRedirectHandler(urllib.request.HTTPRedirectHandler):
    def __init__(self, allowed_origin):
        super().__init__()
        self.allowed_origin = allowed_origin
        self.chain = []

    def redirect_request(self, req, fp, code, msg, headers, newurl):
        resolved = urllib.parse.urljoin(req.full_url, newurl)
        entry = {"from": req.full_url, "status": code, "to": resolved}
        self.chain.append(entry)
        if origin(resolved) != self.allowed_origin:
            entry["followed"] = False
            return None
        entry["followed"] = True
        return super().redirect_request(req, fp, code, msg, headers, resolved)


class LinkParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.hrefs = []

    def handle_starttag(self, tag, attrs):
        for name, value in attrs:
            if name.lower() == "href" and value:
                self.hrefs.append(value)


def safe_headers(headers):
    result = {}
    for key, value in headers.items():
        if key.lower() == "set-cookie":
            result[key] = "[redacted; retained in cookie jar]"
        else:
            result[key] = value
    return result


def read_response(response):
    data = response.read(BODY_LIMIT + 1)
    truncated = len(data) > BODY_LIMIT
    data = data[:BODY_LIMIT]
    charset = response.headers.get_content_charset() or "utf-8"
    body = data.decode(charset, errors="replace")
    return {
        "status": getattr(response, "status", None),
        "reason": getattr(response, "reason", ""),
        "url": response.geturl(),
        "headers": safe_headers(response.headers),
        "body_bytes_captured": len(data),
        "body_truncated": truncated,
        "body": body,
    }


def request(opener, url, method="GET", data=None):
    req = urllib.request.Request(
        url,
        data=data,
        method=method,
        headers={"User-Agent": "student-account-review/1.0", "Accept": "text/html,*/*;q=0.8"},
    )
    try:
        with opener.open(req, timeout=TIMEOUT) as response:
            record = read_response(response)
    except urllib.error.HTTPError as exc:
        record = read_response(exc)
        exc.close()
    except Exception as exc:
        return {"requested_url": url, "method": method, "error": type(exc).__name__ + ": " + str(exc)}
    record["requested_url"] = url
    record["method"] = method
    return record


def same_origin_links(html, page_url):
    parser = LinkParser()
    try:
        parser.feed(html)
    except Exception:
        pass
    found = []
    seen = set()
    for href in parser.hrefs:
        absolute = urllib.parse.urljoin(page_url, href)
        parts = urllib.parse.urlsplit(absolute)
        absolute = urllib.parse.urlunsplit((parts.scheme, parts.netloc, parts.path or "/", parts.query, ""))
        if parts.scheme.lower() not in ("http", "https") or origin(absolute) != origin(BASE):
            continue
        if absolute not in seen:
            seen.add(absolute)
            found.append(absolute)
    return found


def main():
    jar = http.cookiejar.CookieJar()
    redirect_handler = SameOriginRedirectHandler(origin(BASE))
    opener = urllib.request.build_opener(
        urllib.request.HTTPCookieProcessor(jar), redirect_handler
    )

    form_data = urllib.parse.urlencode(
        {"username": "student", "password": "student"}
    ).encode("ascii")
    login = request(opener, LOGIN_URL, method="POST", data=form_data)
    login["redirect_chain"] = list(redirect_handler.chain)
    records = [login]

    linked_pages = []
    if "body" in login:
        page_url = login.get("url", LOGIN_URL)
        linked_pages = same_origin_links(login["body"], page_url)

    for url in linked_pages:
        redirect_handler.chain = []
        record = request(opener, url)
        record["redirect_chain"] = list(redirect_handler.chain)
        records.append(record)

    print(json.dumps({
        "target_origin": BASE,
        "credential_source": "Task-provided public disclosure on the observed home page: student:student",
        "scope": "POST only to the observed /login.php form; GET only direct same-origin href links in its resulting response; same-origin redirects only",
        "body_limit_bytes_per_response": BODY_LIMIT,
        "timeout_seconds_per_request": TIMEOUT,
        "same_origin_links_discovered": linked_pages,
        "records": records,
        "assessment_note": "Authentication state and any admin or flag evidence must be assessed from the recorded application responses; student login success alone does not establish admin access. Set-Cookie values are redacted in output but retained in the session cookie jar.",
    }, ensure_ascii=False))


if __name__ == "__main__":
    main()

