import base64
import hashlib
import json
import os
import socket
import struct
import time

HOST = "192.168.2.254"
PORT = 3306
USERNAME = "student"
PASSWORD = "student"
TIMEOUT = 10

CLIENT_LONG_PASSWORD = 0x00000001
CLIENT_LONG_FLAG = 0x00000004
CLIENT_PROTOCOL_41 = 0x00000200
CLIENT_TRANSACTIONS = 0x00002000
CLIENT_SECURE_CONNECTION = 0x00008000
CLIENT_PLUGIN_AUTH = 0x00080000
CLIENT_CAPABILITIES = (CLIENT_LONG_PASSWORD | CLIENT_LONG_FLAG |
                       CLIENT_PROTOCOL_41 | CLIENT_TRANSACTIONS |
                       CLIENT_SECURE_CONNECTION | CLIENT_PLUGIN_AUTH)


def read_exact(sock, size):
    chunks = []
    remaining = size
    while remaining:
        chunk = sock.recv(remaining)
        if not chunk:
            raise EOFError("connection closed while reading protocol packet")
        chunks.append(chunk)
        remaining -= len(chunk)
    return b"".join(chunks)


def recv_packet(sock):
    header = read_exact(sock, 4)
    size = header[0] | (header[1] << 8) | (header[2] << 16)
    sequence = header[3]
    return sequence, read_exact(sock, size)


def send_packet(sock, sequence, payload):
    if len(payload) > 0xFFFFFF:
        raise ValueError("packet exceeds MySQL protocol packet size")
    header = bytes((len(payload) & 255, (len(payload) >> 8) & 255,
                    (len(payload) >> 16) & 255, sequence & 255))
    sock.sendall(header + payload)


def nul_string(data, offset):
    end = data.find(b"\0", offset)
    if end < 0:
        raise ValueError("unterminated string in server handshake")
    return data[offset:end], end + 1


def parse_handshake(data):
    if not data or data[0] != 10:
        raise ValueError("unsupported or malformed MySQL initial handshake")
    server_version, pos = nul_string(data, 1)
    if pos + 4 + 8 + 1 + 2 > len(data):
        raise ValueError("truncated MySQL handshake")
    connection_id = int.from_bytes(data[pos:pos + 4], "little")
    pos += 4
    seed1 = data[pos:pos + 8]
    pos += 8
    pos += 1  # filler
    caps_low = int.from_bytes(data[pos:pos + 2], "little")
    pos += 2
    capabilities = caps_low
    charset = None
    auth_plugin = "mysql_native_password"
    seed = seed1
    if pos < len(data):
        if pos + 5 > len(data):
            raise ValueError("truncated extended MySQL handshake")
        charset = data[pos]
        pos += 1
        pos += 2  # status flags
        caps_high = int.from_bytes(data[pos:pos + 2], "little")
        pos += 2
        capabilities |= caps_high << 16
        auth_len = data[pos] if pos < len(data) else 0
        pos += 1
        pos += 10  # reserved
        if capabilities & CLIENT_SECURE_CONNECTION and pos < len(data):
            second_len = max(13, auth_len - 8) if auth_len else 13
            second = data[pos:pos + second_len]
            pos += len(second)
            seed = seed1 + second.rstrip(b"\0")
        if capabilities & CLIENT_PLUGIN_AUTH and pos < len(data):
            raw_plugin = data[pos:].split(b"\0", 1)[0]
            if raw_plugin:
                auth_plugin = raw_plugin.decode("ascii", "replace")
    return {
        "server_version": server_version.decode("ascii", "replace"),
        "connection_id": connection_id,
        "capabilities": capabilities,
        "character_set_id": charset,
        "auth_plugin": auth_plugin,
        "challenge_length": len(seed),
        "challenge": seed.rstrip(b"\0"),
    }


def auth_response(plugin, password, challenge):
    challenge = challenge.rstrip(b"\0")
    if not password:
        return b""
    if plugin == "mysql_native_password":
        first = hashlib.sha1(password).digest()
        second = hashlib.sha1(first).digest()
        third = hashlib.sha1(challenge + second).digest()
        return bytes(a ^ b for a, b in zip(first, third))
    if plugin == "caching_sha2_password":
        first = hashlib.sha256(password).digest()
        second = hashlib.sha256(first).digest()
        third = hashlib.sha256(second + challenge).digest()
        return bytes(a ^ b for a, b in zip(first, third))
    raise ValueError("unsupported authentication plugin: " + plugin)


def lenenc(data, pos=0):
    if pos >= len(data):
        raise ValueError("missing length-encoded integer")
    first = data[pos]
    pos += 1
    if first < 0xfb:
        return first, pos
    if first == 0xfc:
        return int.from_bytes(data[pos:pos + 2], "little"), pos + 2
    if first == 0xfd:
        return int.from_bytes(data[pos:pos + 3], "little"), pos + 3
    if first == 0xfe:
        return int.from_bytes(data[pos:pos + 8], "little"), pos + 8
    raise ValueError("NULL or invalid length-encoded integer")


def asn1_items(blob):
    """Yield ASN.1 tag/value pairs, descending into constructed values."""
    pos = 0
    while pos < len(blob):
        tag = blob[pos]
        pos += 1
        if pos >= len(blob):
            break
        first = blob[pos]
        pos += 1
        if first & 0x80:
            count = first & 0x7f
            if count == 0 or count > 4 or pos + count > len(blob):
                break
            size = int.from_bytes(blob[pos:pos + count], "big")
            pos += count
        else:
            size = first
        if pos + size > len(blob):
            break
        value = blob[pos:pos + size]
        pos += size
        yield tag, value
        if tag & 0x20:
            yield from asn1_items(value)


def rsa_public_numbers(pem):
    lines = [line.strip() for line in pem.decode("ascii").splitlines()
             if line and not line.startswith("-----")]
    der = base64.b64decode("".join(lines))
    integers = [int.from_bytes(value, "big") for tag, value in asn1_items(der)
                if tag == 0x02 and value]
    candidates = [value for value in integers if value > 1]
    if len(candidates) < 2:
        raise ValueError("could not parse RSA public key returned by server")
    modulus = max(candidates)
    exponents = [value for value in candidates if value != modulus and value < (1 << 32)]
    if not exponents:
        raise ValueError("RSA public key exponent not found")
    return modulus, exponents[-1]


def rsa_encrypt_mysql_password(pem, password, challenge):
    modulus, exponent = rsa_public_numbers(pem)
    clear = password + b"\0"
    mixed = bytes(value ^ challenge[i % len(challenge)]
                  for i, value in enumerate(clear))
    size = (modulus.bit_length() + 7) // 8
    padding_size = size - len(mixed) - 3
    if padding_size < 8:
        raise ValueError("RSA key is too short for password payload")
    padding = bytearray()
    while len(padding) < padding_size:
        value = os.urandom(1)
        if value != b"\0":
            padding.extend(value)
    encoded = b"\0\x02" + bytes(padding) + b"\0" + mixed
    encrypted = pow(int.from_bytes(encoded, "big"), exponent, modulus)
    return encrypted.to_bytes(size, "big")


def server_error(payload):
    result = {"type": "error", "code": None, "sql_state": None, "message": ""}
    if len(payload) >= 3:
        result["code"] = int.from_bytes(payload[1:3], "little")
    pos = 3
    if len(payload) >= 9 and payload[3:4] == b"#":
        result["sql_state"] = payload[4:9].decode("ascii", "replace")
        pos = 9
    result["message"] = payload[pos:].decode("utf-8", "replace")
    return result


def classify_auth_packet(payload):
    if not payload:
        return {"type": "empty_packet"}
    if payload[0] == 0xff:
        return server_error(payload)
    if payload[0] == 0x00:
        return {"type": "ok", "payload_hex": payload.hex()}
    return {"type": "other", "first_byte": payload[0], "payload_hex": payload.hex()}


def query_identity(sock):
    send_packet(sock, 0, b"\x03SELECT CURRENT_USER(), USER()")
    sequence, first = recv_packet(sock)
    if not first:
        return {"status": "inconclusive", "reason": "empty query response"}
    if first[0] == 0xff:
        return {"status": "query_error", "server_response": server_error(first)}
    if first[0] == 0x00:
        return {"status": "ok_packet", "response_hex": first.hex()}
    count, _ = lenenc(first)
    if count > 1024:
        return {"status": "inconclusive", "reason": "implausible column count",
                "column_count": count}
    # Read column-definition packets, then the non-deprecated EOF marker.
    for _ in range(count):
        sequence, column = recv_packet(sock)
        if column and column[0] == 0xff:
            return {"status": "query_error", "server_response": server_error(column)}
    sequence, marker = recv_packet(sock)
    if marker and marker[0] == 0xff:
        return {"status": "query_error", "server_response": server_error(marker)}
    if not marker or marker[0] != 0xfe:
        return {"status": "inconclusive", "reason": "expected metadata EOF marker",
                "response_hex": marker.hex()}
    rows = []
    while True:
        sequence, packet = recv_packet(sock)
        if packet and packet[0] == 0xff:
            return {"status": "query_error", "server_response": server_error(packet),
                    "rows_seen": rows}
        if packet and packet[0] == 0xfe and len(packet) < 9:
            break
        values = []
        pos = 0
        try:
            for _ in range(count):
                if pos >= len(packet):
                    raise ValueError("truncated text result row")
                if packet[pos] == 0xfb:
                    values.append(None)
                    pos += 1
                else:
                    size, pos = lenenc(packet, pos)
                    if pos + size > len(packet):
                        raise ValueError("truncated field in text result row")
                    values.append(packet[pos:pos + size].decode("utf-8", "replace"))
                    pos += size
            rows.append(values)
        except Exception as exc:
            return {"status": "inconclusive", "reason": str(exc),
                    "row_packet_hex": packet.hex(), "rows_seen": rows}
        if len(rows) >= 10:
            return {"status": "inconclusive", "reason": "row recording cap reached",
                    "rows": rows}
    return {"status": "completed", "column_count": count, "rows": rows}


def main():
    result = {
        "target": f"{HOST}:{PORT}",
        "credential_hypothesis": "publicly observed student:student",
        "transport": "TCP; MySQL protocol; no TLS requested",
        "authenticated": False,
        "exchange_status": "inconclusive",
        "auth_events": [],
    }
    started = time.time()
    try:
        with socket.create_connection((HOST, PORT), timeout=TIMEOUT) as sock:
            sock.settimeout(TIMEOUT)
            sequence, handshake_payload = recv_packet(sock)
            handshake = parse_handshake(handshake_payload)
            result["handshake"] = {key: value for key, value in handshake.items()
                                   if key != "challenge"}
            plugin = handshake["auth_plugin"]
            challenge = handshake["challenge"]
            response = auth_response(plugin, PASSWORD.encode(), challenge)
            capabilities = CLIENT_CAPABILITIES & handshake["capabilities"]
            # Protocol 4.1 and secure auth are required for this response format.
            required = CLIENT_PROTOCOL_41 | CLIENT_SECURE_CONNECTION
            if capabilities & required != required:
                raise ValueError("server does not advertise required protocol capabilities")
            response = (struct.pack("<IIB23s", capabilities, 1024 * 1024, 45, b"")
                        + USERNAME.encode() + b"\0"
                        + bytes((len(response),)) + response)
            if capabilities & CLIENT_PLUGIN_AUTH:
                response += plugin.encode("ascii") + b"\0"
            send_packet(sock, (sequence + 1) & 255, response)

            authenticated = False
            for _ in range(10):
                sequence, payload = recv_packet(sock)
                if not payload:
                    result["auth_events"].append({"type": "empty_server_packet"})
                    break
                if payload[0] == 0xff:
                    event = server_error(payload)
                    result["auth_events"].append(event)
                    result["exchange_status"] = "authentication_rejected"
                    break
                if payload[0] == 0x00:
                    result["auth_events"].append({"type": "authentication_ok",
                                                   "response_hex": payload.hex()})
                    authenticated = True
                    result["exchange_status"] = "authenticated"
                    break
                if payload[0] == 0xfe:
                    switch = payload[1:]
                    switch_plugin_raw, offset = nul_string(switch, 0)
                    switch_plugin = switch_plugin_raw.decode("ascii", "replace")
                    challenge = switch[offset:].rstrip(b"\0")
                    auth = auth_response(switch_plugin, PASSWORD.encode(), challenge)
                    result["auth_events"].append({"type": "auth_switch",
                                                   "plugin": switch_plugin,
                                                   "challenge_length": len(challenge)})
                    send_packet(sock, (sequence + 1) & 255, auth)
                    plugin = switch_plugin
                    continue
                if payload[0] == 0x01 and plugin == "caching_sha2_password":
                    if len(payload) < 2:
                        result["auth_events"].append({"type": "malformed_auth_more_data",
                                                       "payload_hex": payload.hex()})
                        break
                    status_byte = payload[1]
                    if status_byte == 0x03:
                        result["auth_events"].append({"type": "caching_sha2_fast_auth_success"})
                        continue
                    if status_byte == 0x04:
                        result["auth_events"].append({"type": "caching_sha2_full_auth_required"})
                        send_packet(sock, (sequence + 1) & 255, b"\x02")
                        key_sequence, key_packet = recv_packet(sock)
                        if not key_packet or key_packet[0] != 0x01:
                            result["auth_events"].append({
                                "type": "public_key_request_inconclusive",
                                "response_hex": key_packet.hex()})
                            break
                        encrypted = rsa_encrypt_mysql_password(
                            key_packet[1:], PASSWORD.encode(), challenge)
                        send_packet(sock, (key_sequence + 1) & 255, encrypted)
                        continue
                    result["auth_events"].append({"type": "caching_sha2_auth_more_data",
                                                   "status_byte": status_byte,
                                                   "payload_hex": payload.hex()})
                    break
                result["auth_events"].append({"type": "unrecognized_auth_response",
                                               "payload_hex": payload.hex()})
                break

            result["authenticated"] = authenticated
            if authenticated:
                try:
                    result["identity_query"] = query_identity(sock)
                except Exception as exc:
                    result["identity_query"] = {
                        "status": "inconclusive",
                        "error": f"{type(exc).__name__}: {exc}",
                    }
            elif result["exchange_status"] == "inconclusive":
                result["exchange_status"] = "authentication_exchange_incomplete"
    except Exception as exc:
        result["exchange_status"] = "connection_or_protocol_error"
        result["error"] = f"{type(exc).__name__}: {exc}"
    result["elapsed_seconds"] = round(time.time() - started, 3)
    pr
