import http.cookiejar
import json
import re
import urllib.error
import urllib.parse
import urllib.request
from html.parser import HTMLParser

BASE = "http://192.168.2.4:80/"
TARGET_HOST = "192.168.2.4"
TIMEOUT = 15
records = []
redirects = []


class FormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.forms = []
        self.current = None
        self.active_textarea = None
        self.active_select = None

    def handle_starttag(self, tag, attrs):
        attrs = {k.lower(): (v or "") for k, v in attrs}
        if tag.lower() == "form":
            self.current = {"attrs": attrs, "controls": []}
            self.forms.append(self.current)
            return
        if self.current is None:
            return
        if tag.lower() == "input":
            self.current["controls"].append({"kind": "input", "attrs": attrs})
        elif tag.lower() == "textarea":
            control = {"kind": "textarea", "attrs": attrs, "text": ""}
            self.current["controls"].append(control)
            self.active_textarea = control
        elif tag.lower() == "select":
            control = {"kind": "select", "attrs": attrs, "options": []}
            self.current["controls"].append(control)
            self.active_select = control
        elif tag.lower() == "option" and self.active_select is not None:
            self.active_select["options"].append({"attrs": attrs, "text": ""})

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag == "form":
            self.current = None
            self.active_textarea = None
            self.active_select = None
        elif tag == "textarea":
            self.active_textarea = None
        elif tag == "select":
            self.active_select = None
        elif tag == "option" and self.active_select is not None and self.active_select["options"]:
            self.active_select["options"][-1]["closed"] = True

    def handle_data(self, data):
        if self.active_textarea is not None:
            self.active_textarea["text"] += data
        if self.active_select is not None and self.active_select["options"]:
            option = self.active_select["options"][-1]
            if not option.get("closed"):
                option["text"] += data


def cookie_state(jar):
    return [
        {
            "name": c.name,
            "value": c.value,
            "domain": c.domain,
            "path": c.path,
            "secure": c.secure,
            "expires": c.expires,
            "http_only": bool(c._rest.get("HttpOnly") or c._rest.get("httponly")),
        }
        for c in jar
    ]


class RecordingRedirectHandler(urllib.request.HTTPRedirectHandler):
    def _record(self, req, fp, code, msg, headers):
        redirects.append({
            "from": req.full_url,
            "status": code,
            "location": headers.get("Location"),
            "response_headers": list(headers.items()),
        })
        return super().redirect_request(req, fp, code, msg, headers)

    def http_error_301(self, req, fp, code, msg, headers):
        return self._record(req, fp, code, msg, headers)

    def http_error_302(self, req, fp, code, msg, headers):
        return self._record(req, fp, code, msg, headers)

    def http_error_303(self, req, fp, code, msg, headers):
        return self._record(req, fp, code, msg, headers)

    def http_error_307(self, req, fp, code, msg, headers):
        return self._record(req, fp, code, msg, headers)

    def http_error_308(self, req, fp, code, msg, headers):
        return self._record(req, fp, code, msg, headers)


jar = http.cookiejar.CookieJar()
opener = urllib.request.build_opener(
    urllib.request.HTTPCookieProcessor(jar), RecordingRedirectHandler()
)


def request(url, method="GET", data=None, form_fields=None):
    body = None if data is None else urllib.parse.urlencode(data).encode("utf-8")
    headers = {"User-Agent": "Mozilla/5.0 (compatible; session-evidence/1.0)"}
    if body is not None:
        headers["Content-Type"] = "application/x-www-form-urlencoded"
    req = urllib.request.Request(url, data=body, headers=headers, method=method)
    entry = {
        "requested_url": url,
        "method": method,
        "request_headers": list(headers.items()),
        "form_fields": form_fields if form_fields is not None else data,
        "request_body": body.decode("utf-8", "replace") if body is not None else None,
        "cookies_before": cookie_state(jar),
    }
    try:
        with opener.open(req, timeout=TIMEOUT) as response:
            raw = response.read()
            charset = response.headers.get_content_charset() or "utf-8"
            text = raw.decode(charset, "replace")
            entry.update({
                "status": response.status,
                "final_url": response.geturl(),
                "response_headers": list(response.headers.items()),
                "body": text,
                "body_bytes": len(raw),
                "error": None,
            })
    except urllib.error.HTTPError as exc:
        raw = exc.read()
        charset = exc.headers.get_content_charset() or "utf-8"
        entry.update({
            "status": exc.code,
            "final_url": exc.geturl(),
            "response_headers": list(exc.headers.items()),
            "body": raw.decode(charset, "replace"),
            "body_bytes": len(raw),
            "error": "HTTPError",
        })
    except Exception as exc:
        entry.update({
            "status": None,
            "final_url": None,
            "response_headers": [],
            "body": None,
            "body_bytes": 0,
            "error": type(exc).__name__ + ": " + str(exc),
        })
    entry["cookies_after"] = cookie_state(jar)
    records.append(entry)
    return entry


def username_control(form):
    candidates = []
    for control in form["controls"]:
        if control["kind"] != "input":
            continue
        attrs = control["attrs"]
        typ = attrs.get("type", "text").lower()
        name = attrs.get("name", "")
        if typ in ("text", "email") and name:
            candidates.append((control, name.lower()))
    preferred = ("username", "user", "email", "login", "student", "uname", "userid")
    for word in preferred:
        for control, name in candidates:
            if name == word or word in name:
                return control
    return candidates[0][0] if len(candidates) == 1 else None


def make_submission(form):
    controls = form["controls"]
    passwords = [
        c for c in controls
        if c["kind"] == "input" and c["attrs"].get("type", "text").lower() == "password"
        and c["attrs"].get("name")
    ]
    user_control = username_control(form)
    if not passwords or user_control is None:
        return None, "Form has no supported named password and username fields."
    fields = []
    for control in controls:
        kind = control["kind"]
        attrs = control["attrs"]
        name = attrs.get("name")
        if not name or "disabled" in attrs:
            continue
        if kind == "input":
            typ = attrs.get("type", "text").lower()
            if typ in ("submit", "button", "reset", "image", "file"):
                if "required" in attrs and typ == "file":
                    return None, "Required file input cannot be completed from the observed page."
                continue
            if typ in ("checkbox", "radio"):
                if "checked" in attrs:
                    fields.append((name, attrs.get("value", "on")))
                elif "required" in attrs:
                    return None, "A required unchecked checkbox or radio control needs an unknown choice."
                continue
            if control is user_control:
                fields.append((name, "student"))
            elif control in passwords:
                fields.append((name, "student"))
            elif typ == "hidden":
                fields.append((name, attrs.get("value", "")))
            elif "required" in attrs and attrs.get("value", "") == "":
                return None, "Required non-credential input has no observed value."
            elif attrs.get("value"):
                fields.append((name, attrs["value"]))
        elif kind == "select":
            options = control["options"]
            selected = next((o for o in options if "selected" in o["attrs"]), None)
            if selected is None and options:
                selected = options[0]
            if selected is not None:
                fields.append((name, selected["attrs"].get("value", selected["text"])))
            elif "required" in attrs:
                return None, "Required select control has no observed option."
        elif kind == "textarea":
            if "required" in attrs and not control["text"].strip():
                return None, "Required textarea has no observed value."
            if control["text"]:
                fields.append((name, control["text"]))
    return fields, None


def same_target(url):
    p = urllib.parse.urlsplit(url)
    try:
        port = p.port or (443 if p.scheme == "https" else 80)
    except ValueError:
        return False
    return p.scheme in ("http", "https") and p.hostname == TARGET_HOST and port == 80


page = request(BASE)
parsed_forms = FormParser()
if page.get("body") is not None:
    parsed_forms.feed(page["body"])
form_observations = []
login_attempt = "No observed form supported a username/password submission."
for index, form in enumerate(parsed_forms.forms):
    attrs = form["attrs"]
    action = urllib.parse.urljoin(page.get("final_url") or BASE, attrs.get("action") or (page.get("final_url") or BASE))
    method = attrs.get("method", "get").upper()
    form_observations.append({
        "index": index,
        "action": action,
        "method": method,
        "controls": [
            {"kind": c["kind"], "attrs": c["attrs"],
             "options": c.get("options"), "text": c.get("text")}
            for c in form["controls"]
        ],
    })
    fields, why_not = make_submission(form)
    if fields is None:
        continue
    if not same_target(action):
        login_attempt = "A supported credential form was observed, but its action is outside the identified target; it was not submitted."
        continue
    if method not in ("POST", "GET"):
        login_attempt = "A supported credential form used an unsupported method and was not submitted."
        continue
    if method == "POST":
        submitted = request(action, "POST", data=fields, form_fields=fields)
    else:
        query = urllib.parse.urlencode(fields)
        sep = "&" if urllib.parse.urlsplit(action).query else "?"
        submitted = request(action + (sep + query if query else ""), "GET", form_fields=fields)
    login_attempt = "Submitted the observed same-target credential form using student:student."
    break
else:
    if parsed_forms.forms:
        login_attempt = "Observed forms, but none had supported named username and password fields."

admin_url = urllib.parse.urljoin(page.get("final_url") or BASE, "/admin.php")
admin_response = request(admin_url, "GET") if same_target(admin_url) else None

flag_evidence = []
for i, entry in enumerate(records):
    body = entry.get("body")
    if body is not None and re.search(r"flag", body, re.IGNORECASE):
        flag_evidence.append({"request_index": i, "matches": re.findall(r".{0,60}flag.{0,120}", body, re.IGNORECASE)[:20]})

print(json.dumps({
    "target": BASE,
    "login_attempt": login_attempt,
    "forms_observed": form_observations,
    "requests_and_responses": records,
    "redirects": redirects,
    "final_cookie_jar": cookie_state(jar),
    "admin_php_requested": admin_response is not None,
    "admin_php_status": admin_response.get("status") if admin_response else None,
    "flag_text_matches": flag_evidence,
    "assessment_note": "Response content and session evidence are recorded verbatim; a /admin.php response alone does not verify admin authentication. Inspect the returned identity/role and page bodies in context.",
}, ensure_ascii=False))

