import http.cookiejar
import json
import re
import sys
from html.parser import HTMLParser
from urllib.error import HTTPError, URLError
from urllib.parse import urlencode, urljoin, urlsplit
from urllib.request import (
    HTTPRedirectHandler,
    HTTPCookieProcessor,
    Request,
    build_opener,
)

BASE = "http://192.168.2.4:80/"
MAX_REDIRECTS = 10


class NoRedirect(HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


class PageParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.forms = []
        self.links = []
        self.current_form = None
        self.current_select = None
        self.current_option = None
        self.current_textarea = None

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if tag.lower() == "a" and a.get("href"):
            self.links.append(a["href"])
        if tag.lower() == "form":
            self.current_form = {
                "action": a.get("action", ""),
                "method": a.get("method", "get").lower(),
                "inputs": [],
            }
            self.forms.append(self.current_form)
        elif self.current_form is not None and tag.lower() == "input":
            self.current_form["inputs"].append({
                "tag": "input",
                "name": a.get("name", ""),
                "type": a.get("type", "text").lower(),
                "value": a.get("value", ""),
                "required": "required" in a,
                "checked": "checked" in a,
            })
        elif self.current_form is not None and tag.lower() == "textarea":
            self.current_textarea = {
                "tag": "textarea", "name": a.get("name", ""),
                "required": "required" in a, "value": ""
            }
        elif self.current_form is not None and tag.lower() == "select":
            self.current_select = {
                "tag": "select", "name": a.get("name", ""),
                "required": "required" in a, "options": [],
            }
        elif self.current_select is not None and tag.lower() == "option":
            self.current_option = {"value": a.get("value"), "selected": "selected" in a, "text": ""}

    def handle_data(self, data):
        if self.current_textarea is not None:
            self.current_textarea["value"] += data
        if self.current_option is not None:
            self.current_option["text"] += data

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag == "option" and self.current_option is not None:
            if self.current_option["value"] is None:
                self.current_option["value"] = self.current_option["text"].strip()
            if self.current_select is not None:
                self.current_select["options"].append(self.current_option)
            self.current_option = None
        elif tag == "select" and self.current_select is not None:
            options = self.current_select.pop("options")
            selected = [o for o in options if o["selected"]]
            self.current_select["value"] = (selected or options[:1])
            if self.current_form is not None:
                self.current_form["inputs"].append(self.current_select)
            self.current_select = None
        elif tag == "textarea" and self.current_textarea is not None:
            if self.current_form is not None:
                self.current_form["inputs"].append(self.current_textarea)
            self.current_textarea = None
        elif tag == "form":
            self.current_form = None


def response_text(raw, headers):
    charset = None
    try:
        charset = headers.get_content_charset()
    except Exception:
        pass
    try:
        return raw.decode(charset or "utf-8", errors="replace")
    except LookupError:
        return raw.decode("utf-8", errors="replace")


def perform(method, url, data=None, content_type=None):
    """Make one logical request, manually record and follow each redirect."""
    chain = []
    current_method, current_url, current_data = method, url, data
    for redirect_count in range(MAX_REDIRECTS + 1):
        headers = {"User-Agent": "standard-library-session-observer/1.0"}
        if content_type and current_data is not None:
            headers["Content-Type"] = content_type
        req = Request(current_url, data=current_data, headers=headers, method=current_method)
        request_record = {
            "method": current_method,
            "url": current_url,
            "headers": dict(headers),
            "body": current_data.decode("utf-8", "replace") if current_data is not None else None,
        }
        try:
            response = opener.open(req, timeout=12)
        except HTTPError as exc:
            response = exc
        except (URLError, OSError, TimeoutError, ValueError) as exc:
            chain.append({"request": request_record, "transport_error": repr(exc)})
            break
        try:
            raw = response.read()
            status = getattr(response, "status", None) or response.getcode()
            resp_headers = response.headers
            hdrs = dict(resp_headers.items())
            text = response_text(raw, resp_headers)
            record = {
                "request": request_record,
                "response": {
                    "status": status,
                    "reason": getattr(response, "reason", None),
                    "headers": hdrs,
                    "body": text,
                },
            }
        except Exception as exc:
            chain.append({"request": request_record, "response_read_error": repr(exc)})
            try:
                response.close()
            except Exception:
                pass
            break
        finally:
            try:
                response.close()
            except Exception:
                pass
        chain.append(record)
        location = resp_headers.get("Location")
        if status not in (301, 302, 303, 307, 308) or not location:
            break
        if redirect_count == MAX_REDIRECTS:
            record["redirect_limit_reached"] = True
            break
        current_url = urljoin(current_url, location)
        if status == 303 or (status in (301, 302) and current_method.upper() == "POST"):
            current_method, current_data, content_type = "GET", None, None
    return chain


def final_body(chain):
    for item in reversed(chain):
        if "response" in item:
            return item["response"]["body"]
    return ""


def final_url(chain, fallback):
    for item in reversed(chain):
        if "response" in item:
            return item["request"]["url"]
    return fallback


def find_login_url(root_body, root_url):
    parser = PageParser()
    parser.feed(root_body)
    for href in parser.links:
        candidate = urljoin(root_url, href)
        if "login" in urlsplit(candidate).path.lower():
            return candidate
    return urljoin(root_url, "login.php")


def form_submission(form, page_url):
    inputs = form["inputs"]
    passwords = [x for x in inputs if x["type"] == "password" and x.get("name")]
    if len(passwords) != 1:
        return None, "No unique named password field was present."
    password = passwords[0]
    candidates = [
        x for x in inputs
        if x.get("name") and x is not password
        and (x["type"] in ("text", "email") or x["tag"] == "textarea")
    ]
    named = [x for x in candidates if re.search(r"user|login|account|email", x["name"], re.I)]
    usernames = named if len(named) == 1 else (candidates if len(candidates) == 1 else [])
    if len(usernames) != 1:
        return None, "No unique username field could be identified alongside the password field."
    username = usernames[0]

    fields = []
    blocked_required = []
    for item in inputs:
        name = item.get("name", "")
        if not name:
            continue
        typ = item.get("type", "").lower()
        if item is username:
            fields.append((name, "student"))
        elif item is password:
            fields.append((name, "student"))
        elif typ in ("submit", "button", "reset", "file", "image"):
            continue
        elif typ in ("checkbox", "radio"):
            if item.get("checked"):
                fields.append((name, item.get("value", "on")))
            elif item.get("required"):
                blocked_required.append(name)
        elif item["tag"] == "select":
            values = item.get("value", [])
            if values:
                for option in values:
                    fields.append((name, option["value"]))
            elif item.get("required"):
                blocked_required.append(name)
        else:
            value = item.get("value", "")
            if value:
                fields.append((name, value))
            elif item.get("required"):
                blocked_required.append(name)
    if blocked_required:
        return None, "Additional required fields had no observed value: " + ", ".join(blocked_required)
    action = urljoin(page_url, form.get("action") or page_url)
    method = form.get("method", "get").upper()
    return {"method": method, "url": action, "fields": fields}, ""


def body_evidence(text):
    # These are textual indicators for review, not an authentication verdict.
    markers = {}
    for label, pattern in {
        "admin_terms": r"(?i)\badmin(?:istrator)?\b",
        "identity_terms": r"(?i)\b(?:logged\s+in\s+as|welcome|user(?:name)?\s*:)\b",
        "flag_like_text": r"(?i)(?:flag\s*[:=]|[A-Z0-9_]+\{[^}\r\n]+\})",
    }.items():
        markers[label] = re.findall(pattern, text)
    return markers


jar = http.cookiejar.CookieJar()
opener = build_opener(HTTPCookieProcessor(jar), NoRedirect())
result = {
    "target": BASE,
    "operations": [],
    "form_observation": None,
    "credential_submission": {"attempted": False, "reason": "Not yet assessed from the observed form."},
    "admin_php": None,
    "session_cookies": [],
    "identity_role_assessment": None,
    "flag_in_verified_admin_context": False,
}

root_chain = perform("GET", BASE)
result["operations"].append({"purpose": "Fetch current home page and discover login link", "redirect_chain": root_chain})
root_final = final_url(root_chain, BASE)
login_url = find_login_url(final_body(root_chain), root_final)

login_chain = perform("GET", login_url)
result["operations"].append({"purpose": "Fetch login page and inspect form", "redirect_chain": login_chain})
login_final_url = final_url(login_chain, login_url)
login_body = final_body(login_chain)
login_parser = PageParser()
login_parser.feed(login_body)
result["form_observation"] = {
    "page_url": login_final_url,
    "forms": login_parser.forms,
    "links": login_parser.links,
}

submission = None
why = "No login form was present in the returned page."
for form in login_parser.forms:
    candidate, reason = form_submission(form, login_final_url)
    if candidate is not None:
        submission, why = candidate, "Observed form has a unique username field and password field; supplied hidden/default fields are retained."
        break
    why = reason

if submission is not None:
    result["credential_submission"] = {
        "attempted": True,
        "method": submission["method"],
        "url": submission["url"],
        "fields": submission["fields"],
        "reason": why,
    }
    encoded = urlencode(submission["fields"]).encode("utf-8")
    if submission["method"] == "GET":
        separator = "&" if "?" in submission["url"] else "?"
        submit_url = submission["url"] + separator + encoded.decode("ascii")
        submit_chain = perform("GET", submit_url)
    else:
        submit_chain = perform("POST", submission["url"], encoded, "application/x-www-form-urlencoded")
    result["operations"].append({"purpose": "Submit observed login form in retained-cookie session", "redirect_chain": submit_chain})
else:
    result["credential_submission"] = {"attempted": False, "reason": why}

admin_url = urljoin(BASE, "admin.php")
admin_chain = perform("GET", admin_url)
result["operations"].append({"purpose": "Request /admin.php in the same cookie session", "redirect_chain": admin_chain})
admin_body = final_body(admin_chain)
admin_status = None
for item in reversed(admin_chain):
    if "response" in item:
        admin_status = item["response"]["status"]
        break
result["admin_php"] = {
    "requested_url": admin_url,
    "final_url": final_url(admin_chain, admin_url),
    "final_status": admin_status,
    "body": admin_body,
    "text_indicators": body_evidence(admin_body),
}

for cookie in jar:
    result["session_cookies"].append({
        "name": cookie.name,
        "value": cookie.value,
        "domain": cookie.domain,
        "path": cookie.path,
        "secure": cookie.secure,
        "expires": cookie.expires,
        "httponly": bool(cookie.has_nonstandard_attr("HttpOnly")),
    })

# Report evidence for manual assessment; do not infer an admin identity from /admin.php alone.
admin_markers = result["admin_php"]["text_indicators"]
final_admin_url = result["admin_php"]["final_url"]
admin_identity_text = bool(admin_markers.get("admin_terms")) and bool(admin_markers.get("identity_terms"))
redirected_to_login = "login" in urlsplit(final_admin_url).path.lower() and final_admin_url != admin_url
result["identity_role_assessment"] = {
    "admin_page_redirected_to_login": redirected_to_login,
    "admin_page_contains_admin_and_identity_text_indicators": admin_identity_text,
    "note": "Indicators are raw-text clues only. Verify the response content and session context before claiming an authenticated admin identity; an /admin.php response alone is not proof.",
}
result["flag_in_verified_admin_context"] = False
print(json.dumps(result, ensure_ascii=False))

