import http.cookiejar
import json
import re
import urllib.error
import urllib.parse
import urllib.request
from html.parser import HTMLParser

BASE = "http://192.168.2.4:80"
LOGIN_PATH = "/login.php"
ADMIN_PATH = "/admin.php"
MAX_PAGES = 40
MAX_BODY = 20000
TIMEOUT = 8


def origin(url):
    p = urllib.parse.urlsplit(url)
    return (p.scheme.lower(), (p.hostname or "").lower(), p.port or (443 if p.scheme == "https" else 80))


class PageParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links = []
        self.forms = []
        self.current_form = None
        self.title = False
        self.title_text = []
        self.text_parts = []
        self.in_script_or_style = 0

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if tag == "form":
            self.current_form = {"attrs": a, "fields": []}
            self.forms.append(self.current_form)
        elif tag == "input" and self.current_form is not None:
            self.current_form["fields"].append(a)
        elif tag == "button" and self.current_form is not None:
            self.current_form["fields"].append({"name": a.get("name", ""), "type": "button", "value": a.get("value", "")})
        elif tag == "a" and a.get("href"):
            self.links.append(a["href"])
        elif tag == "title":
            self.title = True
        elif tag in ("script", "style"):
            self.in_script_or_style += 1

    def handle_endtag(self, tag):
        if tag == "form":
            self.current_form = None
        elif tag == "title":
            self.title = False
        elif tag in ("script", "style") and self.in_script_or_style:
            self.in_script_or_style -= 1

    def handle_data(self, data):
        if self.title:
            self.title_text.append(data)
        if not self.in_script_or_style and data.strip():
            self.text_parts.append(data.strip())


class SameOriginRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        if origin(newurl) != origin(BASE):
            raise urllib.error.HTTPError(newurl, code, "cross-origin redirect blocked", headers, fp)
        return super().redirect_request(req, fp, code, msg, headers, newurl)


jar = http.cookiejar.CookieJar()
opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(jar), SameOriginRedirect())
records = []
visited = set()


def safe_url(url):
    p = urllib.parse.urlsplit(url)
    # Do not report query values, which may contain form data or tokens.
    return urllib.parse.urlunsplit((p.scheme, p.netloc, p.path, "<redacted>" if p.query else "", ""))


def fetch(url, method="GET", data=None, label=None):
    headers = {"User-Agent": "Application-context-inspection/1.0", "Accept": "text/html,application/xhtml+xml,*/*;q=0.8"}
    req = urllib.request.Request(url, data=data, headers=headers, method=method)
    if data is not None:
        req.add_header("Content-Type", "application/x-www-form-urlencoded")
    rec = {"requested_url": safe_url(url), "method": method}
    if label:
        rec["purpose"] = label
    try:
        with opener.open(req, timeout=TIMEOUT) as response:
            raw = response.read(MAX_BODY + 1)
            rec.update({"status": response.status, "final_url": safe_url(response.geturl()),
                        "headers": {k: v for k, v in response.headers.items()
                                    if k.lower() not in ("set-cookie", "set-cookie2")},
                        "body_truncated": len(raw) > MAX_BODY})
    except urllib.error.HTTPError as e:
        raw = e.read(MAX_BODY + 1)
        rec.update({"status": e.code, "final_url": safe_url(e.geturl()),
                    "headers": {k: v for k, v in e.headers.items()
                                if k.lower() not in ("set-cookie", "set-cookie2")},
                    "body_truncated": len(raw) > MAX_BODY, "http_error": str(e.reason)})
    except Exception as e:
        raw = b""
        rec.update({"request_error": type(e).__name__ + ": " + str(e), "body_truncated": False})
    body = raw[:MAX_BODY].decode("utf-8", errors="replace")
    rec["body_bytes_captured"] = len(raw[:MAX_BODY])
    rec["body"] = body
    parser = PageParser()
    try:
        parser.feed(body)
        rec["title"] = " ".join(" ".join(parser.title_text).split())
        rec["visible_text"] = " ".join(" ".join(parser.text_parts).split())[:6000]
        rec["forms"] = [{"action": f["attrs"].get("action", ""),
                          "method": f["attrs"].get("method", "get").upper(),
                          "inputs": [{"name": x.get("name", ""), "type": x.get("type", "text").lower(),
                                      "value_present": bool(x.get("value"))} for x in f["fields"]]}
                         for f in parser.forms]
        rec["links"] = parser.links
    except Exception as e:
        parser = PageParser()
        rec["parse_error"] = type(e).__name__ + ": " + str(e)
    records.append(rec)
    rec["_links"] = getattr(parser, "links", [])
    rec["_forms"] = getattr(parser, "forms", [])
    return rec


def same_origin_url(base_url, href):
    target = urllib.parse.urljoin(base_url, href)
    p = urllib.parse.urlsplit(target)
    if origin(target) != origin(BASE) or p.scheme not in ("http", "https"):
        return None
    if p.path.lower().split("/")[-1].startswith(("logout", "signout", "delete", "remove")):
        return None
    return urllib.parse.urlunsplit((p.scheme, p.netloc, p.path or "/", p.query, ""))


login_url = BASE + LOGIN_PATH
initial = fetch(login_url, label="observed student-facing login route")
visited.add(login_url)
submission = {"attempted": False, "reason": "No clearly identifiable username/password login form was found."}
post_rec = None

# Submit only the known public pair, once, when the observed form has a password
# field and a text-like username field. Other form fields (including hidden fields)
# are retained as supplied by the page.
for form in initial.get("_forms", []):
    attrs = form.get("attrs", {})
    fields = form.get("fields", [])
    password_fields = [x for x in fields if x.get("type", "text").lower() == "password" and x.get("name")]
    text_fields = [x for x in fields if x.get("name") and x.get("type", "text").lower() in ("text", "email")]
    if not password_fields or not text_fields:
        continue
    user_field = next((x for x in text_fields if re.search(r"user|login|email", x.get("name", ""), re.I)), text_fields[0])
    pass_field = password_fields[0]
    values = []
    for field in fields:
        name = field.get("name")
        if not name or field.get("type", "text").lower() in ("submit", "button", "image", "file", "reset"):
            continue
        value = field.get("value", "")
        if name == user_field["name"]:
            value = "student"
        elif name == pass_field["name"]:
            value = "student"
        values.append((name, value))
    action = urllib.parse.urljoin(login_url, attrs.get("action") or login_url)
    if origin(action) != origin(BASE):
        submission = {"attempted": False, "reason": "Login form action was not same-origin; no credentials submitted."}
        break
    method = attrs.get("method", "get").upper()
    if method not in ("GET", "POST"):
        submission = {"attempted": False, "reason": "Login form method was not GET or POST; no credentials submitted."}
        break
    encoded = urllib.parse.urlencode(values)
    if method == "GET":
        sep = "&" if urllib.parse.urlsplit(action).query else "?"
        target = action + (sep + encoded if encoded else "")
        post_rec = fetch(target, method="GET", label="single student credential submission")
    else:
        post_rec = fetch(action, method="POST", data=encoded.encode("utf-8"), label="single student credential submission")
    submission = {"attempted": True, "method": method, "action": safe_url(action),
                  "credential_pair": "student:student", "attempts": 1}
    break

# Examine same-origin links from the login response and the post-submission response.
queue = []
for source in (initial, post_rec):
    if not source:
        continue
    base_url = source.get("final_url") or safe_url(login_url)
    for href in source.get("_links", []):
        url = same_origin_url(base_url, href)
        if url and url not in visited and url not in queue:
            queue.append(url)

admin_url = BASE + ADMIN_PATH
if admin_url not in visited and admin_url not in queue:
    queue.insert(0, admin_url)

while queue and len(visited) < MAX_PAGES:
    url = queue.pop(0)
    if url in visited:
        continue
    visited.add(url)
    rec = fetch(url, label="same-origin navigation" if urllib.parse.urlsplit(url).path != ADMIN_PATH else "known /admin.php route in student context")
    base_url = rec.get("final_url") or url
    for href in rec.get("_links", []):
        linked = same_origin_url(base_url, href)
        if linked and linked not in visited and linked not in queue:
            queue.append(linked)

# Report cookie names only; never emit values. Session establishment requires
# application-specific evidence in the response, not merely a cookie or redirect.
texts = [r.get("visible_text", "") for r in records]
combined = "\n".join(texts).lower()
indicators = []
for pattern, label in [
    (r"\blogout\b|\bsign out\b", "logout/sign-out text"),
    (r"\bwelcome\s+(student|back)\b", "student/back welcome text"),
    (r"\bstudent\s+(dashboard|profile|account)\b", "student account/dashboard text"),
    (r"\bisadmin\s*[=:]\s*1\b", "isAdmin=1 text"),
]:
    if re.search(pattern, combined, re.I):
        indicators.append(label)
login_forms_remain = any("password" in [i.get("type", "") for i in r.get("forms", []) for i in f.get("inputs", [])]
                        for r in records if urllib.parse.urlsplit(r.get("final_url", "")).path == LOGIN_PATH)
if submission.get("attempted") and indicators:
    session_assessment = {"state": "possible_session_evidence_observed", "evidence_indicators": indicators,
                          "note": "Review the recorded page content and request sequence; indicators are not independently proof of authentication."}
elif submission.get("attempted") and login_forms_remain:
    session_assessment = {"state": "login_form_still_present", "evidence_indicators": indicators}
else:
    session_assessment = {"state": "not_established_by_recorded_application_evidence", "evidence_indicators": indicators}

output_records = []
for rec in records:
    output_records.append({k: v for k, v in rec.items() if not k.startswith("_")})
print(json.dumps({
    "target": BASE,
    "scope": "same-origin HTTP application at 192.168.2.4:80",
    "credentials": "only the known public student:student pair; no admin credentials attempted",
    "login_submission": submission,
    "session_assessment": session_assessment,
    "session_cookie_names": sorted({c.name for c in jar}),
    "pages_examined": len(visited),
    "page_cap": MAX_PAGES,
    "unvisited_same_origin_links_remaining": len(queue),
    "coverage_note": "Only captured bodies up to the stated per-response limit were parsed. Same-origin anchor links were followed; logout/destructive-style links and cross-origin links were not followed. Errors and truncation are recorded per response.",
    "records": output_records
}, ensure_ascii=False))

