import http.client
import json
import re
import sys
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit, urldefrag

HOST = "192.168.2.4"
PORT = 80
BASE = "http://192.168.2.4/"
KNOWN_PATHS = {"/", "/admin.php"}
TIMEOUT = 6

class RefParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.refs = []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        for key in ("href", "src", "action"):
            value = attrs.get(key)
            if value:
                self.refs.append(value)
        if tag.lower() == "meta" and attrs.get("http-equiv", "").lower() == "refresh":
            match = re.search(r"url\s*=\s*['\"]?([^'\";]+)", attrs.get("content", ""), re.I)
            if match:
                self.refs.append(match.group(1).strip())


def normalize_reference(value, source_url):
    try:
        absolute = urldefrag(urljoin(source_url, value.strip()))[0]
        parsed = urlsplit(absolute)
        if parsed.scheme.lower() != "http" or parsed.hostname != HOST:
            return None
        if parsed.port not in (None, PORT) or parsed.username or parsed.password:
            return None
        path = parsed.path or "/"
        if parsed.query:
            path += "?" + parsed.query
        return path
    except (ValueError, AttributeError):
        return None


def request(method, path):
    target = path if path.startswith("/") else "/" + path
    result = {
        "request": {"method": method, "host": HOST, "port": PORT, "path": target},
        "response": None,
        "parser_status": "not_started",
        "error": None,
        "references": [],
        "material_indicators": []
    }
    conn = http.client.HTTPConnection(HOST, PORT, timeout=TIMEOUT)
    try:
        conn.request(method, target, headers={"Host": HOST, "User-Agent": "in-scope-http-metadata-check/1.0", "Connection": "close"})
        response = conn.getresponse()
        body = response.read()
        headers = response.getheaders()
        decoded = body.decode("utf-8", errors="replace")
        result["response"] = {
            "status": response.status,
            "reason": response.reason,
            "headers": headers,
            "body_bytes": len(body),
            "body_text": decoded if method != "HEAD" else ""
        }
        result["parser_status"] = "http_response_and_headers_parsed"
        header_map = {}
        for key, value in headers:
            header_map.setdefault(key.lower(), []).append(value)
        candidates = []
        for name in ("location", "link"):
            for value in header_map.get(name, []):
                if name == "location":
                    candidates.append(value)
                else:
                    candidates.extend(re.findall(r"<([^>]+)>", value))
        if method != "HEAD" and decoded:
            parser = RefParser()
            try:
                parser.feed(decoded)
                parser.close()
                candidates.extend(parser.refs)
            except Exception as exc:
                result["body_reference_parse_error"] = str(exc)
        seen = set()
        for candidate in candidates:
            normalized = normalize_reference(candidate, "http://" + HOST + target)
            if normalized and normalized not in seen:
                seen.add(normalized)
                result["references"].append(normalized)
        relevant_headers = {"www-authenticate", "set-cookie", "allow", "location", "link"}
        for name in relevant_headers:
            if name in header_map:
                result["material_indicators"].append({"source": "header", "name": name, "values": header_map[name]})
        marker_patterns = [r"(?i)password", r"(?i)username", r"(?i)credential", r"(?i)token", r"(?i)secret", r"(?i)isAdmin"]
        for pattern in marker_patterns:
            if re.search(pattern, decoded):
                result["material_indicators"].append({"source": "response_body", "indicator": pattern})
    except Exception as exc:
        result["parser_status"] = "no_complete_http_response"
        result["error"] = repr(exc)
    finally:
        conn.close()
    return result


def main():
    observations = []
    discovered = set()
    # Different request methods against the two URLs identified in prior evidence;
    # no GET is repeated for either previously examined URL.
    for path in ("/", "/admin.php"):
        for method in ("HEAD", "OPTIONS"):
            observation = request(method, path)
            observations.append(observation)
            discovered.update(observation.get("references", []))

    # Retrieve only references newly exposed by the metadata/method responses.
    # Known examined paths are excluded, and all references are constrained to this host.
    new_paths = sorted(path for path in discovered if path.split("?", 1)[0] not in KNOWN_PATHS)
    followed = []
    for path in new_paths:
        observation = request("GET", path)
        followed.append(observation)

    output = {
        "target": {"host": HOST, "port": PORT, "scheme": "http"},
        "prior_coverage_assumed_from_supplied_evidence": sorted(KNOWN_PATHS),
        "method_coverage": ["HEAD", "OPTIONS"],
        "newly_observed_references": sorted(discovered),
        "new_references_retrieved_with_get": new_paths,
        "observations": observations,
        "followed_reference_observations": followed,
        "interpretation": "Material indicators are leads only. No authentication attempt was made; HTTP response success, advertised methods, or text markers do not establish an admin session or flag. Only the listed requests were examined; other routes and authentication paths remain unassessed."
    }
    print(json.dumps(output, ensure_ascii=False))


if __name__ == "__main__":
    main()

