import hashlib
import json
import socket
import sys

HOST = "192.168.2.254"
PORT = 3306
TIMEOUT = 4.0
# Small, non-empty default examples only. Values are never printed in output.
CANDIDATES = [
    ("root", "root", "common root/root default example"),
    ("root", "password", "common root/password default example"),
    ("admin", "admin", "common admin/admin default example"),
]

CLIENT_LONG_PASSWORD = 0x00000001
CLIENT_PROTOCOL_41 = 0x00000200
CLIENT_TRANSACTIONS = 0x00002000
CLIENT_SECURE_CONNECTION = 0x00008000
CLIENT_PLUGIN_AUTH = 0x00080000


def recvall(sock, count):
    chunks = []
    remaining = count
    while remaining:
        chunk = sock.recv(remaining)
        if not chunk:
            raise EOFError("connection closed while reading a MySQL packet")
        chunks.append(chunk)
        remaining -= len(chunk)
    return b"".join(chunks)


def read_packet(sock):
    header = recvall(sock, 4)
    length = header[0] | (header[1] << 8) | (header[2] << 16)
    return header[3], recvall(sock, length)


def write_packet(sock, sequence, payload):
    length = len(payload)
    header = bytes((length & 255, (length >> 8) & 255,
                    (length >> 16) & 255, sequence & 255))
    sock.sendall(header + payload)


def packet_record(sequence, payload):
    return {
        "sequence_id": sequence,
        "payload_length": len(payload),
        "payload_hex": payload.hex(),
    }


def nul_string(data, offset):
    end = data.find(b"\x00", offset)
    if end < 0:
        raise ValueError("unterminated string in MySQL handshake")
    return data[offset:end], end + 1


def parse_handshake(payload):
    if not payload:
        raise ValueError("empty initial server packet")
    if payload[0] != 10:
        raise ValueError("server packet is not a MySQL protocol-10 handshake")
    server_version, pos = nul_string(payload, 1)
    if pos + 4 + 8 + 1 + 2 > len(payload):
        raise ValueError("truncated MySQL handshake")
    connection_id = int.from_bytes(payload[pos:pos + 4], "little")
    pos += 4
    salt_first = payload[pos:pos + 8]
    pos += 9  # eight salt bytes and filler
    caps_low = int.from_bytes(payload[pos:pos + 2], "little")
    pos += 2
    caps = caps_low
    plugin = b"mysql_native_password"
    salt = salt_first
    if pos < len(payload):
        if pos + 5 > len(payload):
            raise ValueError("truncated extended MySQL handshake")
        pos += 1  # character set
        pos += 2  # status flags
        caps |= int.from_bytes(payload[pos:pos + 2], "little") << 16
        pos += 2
        auth_data_len = payload[pos]
        pos += 1
        pos += 10  # reserved bytes
        if caps & CLIENT_SECURE_CONNECTION:
            desired = max(13, auth_data_len - 8) if auth_data_len else 13
            second = payload[pos:pos + desired]
            pos += len(second)
            salt += second.rstrip(b"\x00")
        if caps & CLIENT_PLUGIN_AUTH and pos < len(payload):
            plugin_raw = payload[pos:].split(b"\x00", 1)[0]
            if plugin_raw:
                plugin = plugin_raw
    return {
        "server_version": server_version.decode("ascii", "replace"),
        "connection_id": connection_id,
        "capabilities": caps,
        "plugin": plugin.decode("ascii", "replace"),
        "salt": salt,
    }


def auth_token(plugin, password, salt):
    password_bytes = password.encode("utf-8")
    if plugin == "mysql_native_password":
        if not password_bytes:
            return b""
        stage1 = hashlib.sha1(password_bytes).digest()
        stage2 = hashlib.sha1(stage1).digest()
        challenge = hashlib.sha1(salt + stage2).digest()
        return bytes(a ^ b for a, b in zip(stage1, challenge))
    if plugin == "caching_sha2_password":
        if not password_bytes:
            return b""
        stage1 = hashlib.sha256(password_bytes).digest()
        stage2 = hashlib.sha256(stage1).digest()
        challenge = hashlib.sha256(stage2 + salt).digest()
        return bytes(a ^ b for a, b in zip(stage1, challenge))
    raise ValueError("unsupported authentication plugin: " + plugin)


def parse_error(payload):
    result = {"kind": "error", "raw_payload_hex": payload.hex()}
    if not payload or payload[0] != 0xff:
        result["parse_status"] = "not_an_error_packet"
        return result
    if len(payload) >= 3:
        result["error_code"] = int.from_bytes(payload[1:3], "little")
    pos = 3
    if len(payload) >= 9 and payload[3:4] == b"#":
        result["sql_state"] = payload[4:9].decode("ascii", "replace")
        pos = 9
    result["message"] = payload[pos:].decode("utf-8", "replace")
    result["parse_status"] = "parsed"
    return result


def describe_response(payload):
    if not payload:
        return {"kind": "empty", "raw_payload_hex": ""}
    marker = payload[0]
    if marker == 0xff:
        return parse_error(payload)
    if marker == 0x00:
        return {"kind": "ok_packet", "authenticated_session_established": True,
                "raw_payload_hex": payload.hex()}
    if marker == 0x01:
        status = payload[1] if len(payload) > 1 else None
        return {"kind": "auth_more_data", "status_byte": status,
                "meaning": "fast_auth_success" if status == 0x03 else
                           "full_authentication_requested" if status == 0x04 else "unknown",
                "raw_payload_hex": payload.hex()}
    if marker == 0xfe:
        return {"kind": "authentication_switch", "raw_payload_hex": payload.hex()}
    return {"kind": "other_packet", "first_byte": marker,
            "raw_payload_hex": payload.hex()}


def run_candidate(user, password, category):
    result = {
        "account": user,
        "credential_category": category,
        "credential_value_disclosed": False,
        "attempted": False,
        "protocol_parse_status": "not_started",
        "authenticated_session_established": False,
        "server_packets": [],
        "client_messages": [],
    }
    try:
        with socket.create_connection((HOST, PORT), timeout=TIMEOUT) as sock:
            sock.settimeout(TIMEOUT)
            seq, greeting = read_packet(sock)
            result["server_packets"].append(packet_record(seq, greeting))
            if greeting and greeting[0] == 0xff:
                result["protocol_parse_status"] = "initial_server_error"
                result["server_response"] = parse_error(greeting)
                return result
            handshake = parse_handshake(greeting)
            result["protocol_parse_status"] = "handshake_parsed"
            result["server"] = {
                "version": handshake["server_version"],
                "authentication_plugin": handshake["plugin"],
                "capabilities_hex": "0x%08x" % handshake["capabilities"],
            }
            plugin = handshake["plugin"]
            if plugin not in ("mysql_native_password", "caching_sha2_password"):
                result["protocol_parse_status"] = "unsupported_authentication_plugin"
                result["detail"] = "No credential response sent for unsupported plugin."
                return result
            try:
                token = auth_token(plugin, password, handshake["salt"])
            except Exception as exc:
                result["protocol_parse_status"] = "authentication_token_error"
                result["detail"] = str(exc)
                return result

            caps = (CLIENT_LONG_PASSWORD | CLIENT_PROTOCOL_41 |
                    CLIENT_TRANSACTIONS | CLIENT_SECURE_CONNECTION | CLIENT_PLUGIN_AUTH)
            caps &= handshake["capabilities"] | CLIENT_LONG_PASSWORD | CLIENT_PROTOCOL_41
            # Do not claim plugin-auth support if the server did not advertise it.
            if not (handshake["capabilities"] & CLIENT_PLUGIN_AUTH):
                caps &= ~CLIENT_PLUGIN_AUTH
            response = (caps.to_bytes(4, "little") +
                        (16 * 1024 * 1024).to_bytes(4, "little") +
                        bytes((45,)) + b"\x00" * 23 +
                        user.encode("utf-8") + b"\x00" +
                        bytes((len(token),)) + token)
            if caps & CLIENT_PLUGIN_AUTH:
                response += plugin.encode("ascii") + b"\x00"
            write_packet(sock, (seq + 1) & 255, response)
            result["attempted"] = True
            result["client_messages"].append({
                "type": "initial_authentication_response",
                "sequence_id": (seq + 1) & 255,
                "plugin": plugin,
                "authentication_response_length": len(token),
                "authentication_response_omitted": True,
            })

            response_seq, response_payload = read_packet(sock)
            result["server_packets"].append(packet_record(response_seq, response_payload))
            parsed = describe_response(response_payload)
            result["server_response"] = parsed
            if parsed.get("kind") == "ok_packet":
                result["authenticated_session_established"] = True
                result["protocol_parse_status"] = "authentication_success_parsed"
                return result
            if parsed.get("kind") == "error":
                result["protocol_parse_status"] = "authentication_rejection_parsed"
                return result

            if parsed.get("kind") == "authentication_switch":
                switch_data = response_payload[1:]
                switch_plugin_bytes, split_at = (switch_data.split(b"\x00", 1) + [b""])[:2] if b"\x00" in switch_data else (switch_data, b"")
                switch_plugin = switch_plugin_bytes.decode("ascii", "replace")
                switch_salt = split_at.rstrip(b"\x00")
                result["server_response"]["switch_plugin"] = switch_plugin
                if switch_plugin not in ("mysql_native_password", "caching_sha2_password"):
                    result["protocol_parse_status"] = "unsupported_authentication_switch"
                    return result
                switch_token = auth_token(switch_plugin, password, switch_salt)
                write_packet(sock, (response_seq + 1) & 255, switch_token)
                result["client_messages"].append({
                    "type": "authentication_switch_response",
                    "sequence_id": (response_seq + 1) & 255,
                    "plugin": switch_plugin,
                    "authentication_response_length": len(switch_token),
                    "authentication_response_omitted": True,
                })
                response_seq, response_payload = read_packet(sock)
                result["server_packets"].append(packet_record(response_seq, response_payload))
                parsed = describe_response(response_payload)
                result["server_response_after_switch"] = parsed
                if parsed.get("kind") == "ok_packet":
                    result["authenticated_session_established"] = True
                    result["protocol_parse_status"] = "authentication_success_parsed"
                elif parsed.get("kind") == "error":
                    result["protocol_parse_status"] = "authentication_rejection_parsed"
                elif parsed.get("kind") == "auth_more_data" and parsed.get("status_byte") == 0x04:
                    result["protocol_parse_status"] = "inconclusive_full_authentication_requested"
                    result["detail"] = "Server requested full authentication; no password was sent in cleartext."
                else:
                    result["protocol_parse_status"] = "inconclusive_unexpected_authentication_response"
                return result

            if parsed.get("kind") == "auth_more_data" and parsed.get("status_byte") == 0x03:
                response_seq, response_payload = read_packet(sock)
                result["server_packets"].append(packet_record(response_seq, response_payload))
                parsed = describe_response(response_payload)
                result["server_response_after_fast_auth"] = parsed
                if parsed.get("kind") == "ok_packet":
                    result["authenticated_session_established"] = True
                    result["protocol_parse_status"] = "authentication_success_parsed"
                elif parsed.get("kind") == "error":
                    result["protocol_parse_status"] = "authentication_rejection_parsed"
                else:
                    result["protocol_parse_status"] = "inconclusive_unexpected_authentication_response"
                return result
            if parsed.get("kind") == "auth_more_data" and parsed.get("status_byte") == 0x04:
                result["protocol_parse_status"] = "inconclusive_full_authentication_requested"
                result["detail"] = "Server requested full authentication; no password was sent in cleartext."
                return result
            result["protocol_parse_status"] = "inconclusive_unexpected_authentication_response"
            return result
    except (OSError, EOFError, ValueError, IndexError) as exc:
        result["error"] = type(exc).__name__ + ": " + str(exc)
        if result["protocol_parse_status"] == "not_started":
            result["protocol_parse_status"] = "connection_or_handshake_inconclusive"
        else:
            result["protocol_parse_status"] = "protocol_exchange_inconclusive"
        return result


def main():
    output = {
        "target": "%s:%d" % (HOST, PORT),
        "scope": "Only the observed MySQL service; no database query is issued.",
        "credential_values_printed": False,
        "tests": [],
        "authenticated_session_established": False,
        "coverage_note": "Only the listed non-empty default examples are checked. Rejection does not rule out other authentication paths.",
    }
    for user, password, category in CANDIDATES:
        result = run_candidate(user, password, category)
        output["tests"].append(result)
        if result.get("authenticated_session_established"):
            output["authenticated_session_established"] = True
            output["coverage_note"] = "Stopped after an authenticated session was established; later candidates were not tested. No database query was issued."
            break
    print(json.dumps(output, ensure_ascii=False, separators=(",", ":")))


if __name__ == "__main__":
    main()

