import json
import re
import sys
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit, urlunsplit

import framework_evidence

BASE = "http://192.168.2.4/"
AUTH_RE = re.compile(r"(?:admin|auth|login|signin|sign-in|account|session|user)", re.I)
SITEMAP_RE = re.compile(r"(?:^|/)sitemap(?:[-_a-z0-9]*)?\.xml(?:$|[?#])", re.I)


def same_origin(url):
    a, b = urlsplit(BASE), urlsplit(url)
    return (a.scheme.lower(), a.hostname, a.port or 80) == (b.scheme.lower(), b.hostname, b.port or 80)


def relevant_url(url):
    return bool(AUTH_RE.search(urlsplit(url).path))


def stdout_values(value):
    found = []
    if isinstance(value, dict):
        for key, child in value.items():
            if key == "stdout" and isinstance(child, str):
                found.append(child)
            else:
                found.extend(stdout_values(child))
    elif isinstance(value, list):
        for child in value:
            found.extend(stdout_values(child))
    return found


def parse_http(raw):
    # curl --include normally emits one response. Preserve raw output separately;
    # this parser reports the final recognizable status/header block.
    status = None
    headers = {}
    body = raw
    matches = list(re.finditer(r"HTTP/\S+\s+(\d{3})[^\r\n]*\r?\n", raw))
    if matches:
        match = matches[-1]
        status = int(match.group(1))
        end = raw.find("\r\n\r\n", match.start())
        sep_len = 4
        if end < 0:
            end = raw.find("\n\n", match.start())
            sep_len = 2
        if end >= 0:
            header_text = raw[match.end():end]
            body = raw[end + sep_len:]
            for line in header_text.splitlines():
                if ":" in line:
                    k, v = line.split(":", 1)
                    headers[k.strip().lower()] = v.strip()
    return status, headers, body


class Links(HTMLParser):
    def __init__(self):
        super().__init__()
        self.urls = []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        for key in ("href", "action"):
            value = attrs.get(key)
            if value:
                self.urls.append(value.strip())


def resolved_candidates(values, base_url):
    result = set()
    for value in values:
        value = value.strip().strip("<>\"'")
        if not value or value.startswith(("#", "javascript:", "mailto:")):
            continue
        url = urljoin(base_url, value)
        if same_origin(url) and (relevant_url(url) or SITEMAP_RE.search(urlsplit(url).path)):
            result.add(url)
    return result


def main():
    queue = [urljoin(BASE, "robots.txt"), urljoin(BASE, "sitemap.xml")]
    seen = set()
    records = []
    while queue:
        url = queue.pop(0)
        if url in seen:
            continue
        seen.add(url)
        record = {"resource": url}
        try:
            envelope = framework_evidence.run_tool([
                "curl", "--silent", "--show-error", "--include", "--max-time", "15", url
            ])
            record["tool_envelope"] = envelope
            streams = stdout_values(envelope)
            raw = "\n".join(streams)
            if not raw and isinstance(envelope, str):
                raw = envelope
            status, headers, body = parse_http(raw)
            record["http_status"] = status
            record["response_headers"] = headers
            record["raw_response_text"] = raw
            record["parse_status"] = "http_status_and_headers_parsed" if status is not None else "http_response_not_parsed"
            record["discovered_authentication_resources"] = []
            candidates = set()
            ctype = headers.get("content-type", "").lower()
            path = urlsplit(url).path.lower()
            if path.endswith("/robots.txt") or path == "/robots.txt" or "text/plain" in ctype:
                try:
                    for line in body.splitlines():
                        if ":" not in line:
                            continue
                        key, value = line.split(":", 1)
                        key, value = key.strip().lower(), value.strip()
                        if key == "sitemap":
                            candidates.update(resolved_candidates([value], url))
                        elif key in ("disallow", "allow") and value:
                            candidate = urljoin(BASE, value)
                            if same_origin(candidate) and relevant_url(candidate):
                                candidates.add(candidate)
                    record["resource_parse_status"] = "robots_directives_parsed"
                except Exception as exc:
                    record["resource_parse_status"] = "robots_parse_error: " + repr(exc)
            elif path.endswith(".xml") or "xml" in ctype:
                try:
                    import xml.etree.ElementTree as ET
                    root = ET.fromstring(body)
                    locs = [element.text.strip() for element in root.iter() if element.tag.rsplit("}", 1)[-1].lower() == "loc" and element.text]
                    candidates.update(resolved_candidates(locs, url))
                    record["resource_parse_status"] = "sitemap_xml_parsed"
                    record["sitemap_locations_found"] = len(locs)
                except Exception as exc:
                    record["resource_parse_status"] = "xml_parse_error: " + repr(exc)
            else:
                try:
                    parser = Links()
                    parser.feed(body)
                    candidates.update(resolved_candidates(parser.urls, url))
                    record["resource_parse_status"] = "html_links_parsed"
                except Exception as exc:
                    record["resource_parse_status"] = "html_parse_error: " + repr(exc)
            auth_candidates = sorted(u for u in candidates if relevant_url(u))
            record["discovered_authentication_resources"] = auth_candidates
            for candidate in sorted(candidates):
                if candidate not in seen and candidate not in queue:
                    queue.append(candidate)
        except Exception as exc:
            record["execution_error"] = repr(exc)
            record["parse_status"] = "not_available"
            record["resource_parse_status"] = "not_attempted"
        records.append(record)
    print(json.dumps({"target": BASE, "resources_examined": records,
                      "coverage_note": "Only the public discovery resources and same-origin sitemap or authentication-relevant resources identified by their responses were requested. No credentials or form submissions were attempted."}, ensure_ascii=False))


if __name__ == "__main__":
    main()

