import json
import socket
import struct
import sys

HOST = "192.168.2.254"
PORT = 3306
TIMEOUT = 5.0
MAX_PACKET = 16 * 1024 * 1024


def recv_exact(sock, count):
    chunks = []
    remaining = count
    while remaining:
        part = sock.recv(remaining)
        if not part:
            raise EOFError("connection closed while reading a MySQL packet")
        chunks.append(part)
        remaining -= len(part)
    return b"".join(chunks)


def read_packet(sock):
    header = recv_exact(sock, 4)
    length = header[0] | (header[1] << 8) | (header[2] << 16)
    sequence = header[3]
    if length > MAX_PACKET:
        raise ValueError("MySQL packet exceeds the configured observation limit")
    return sequence, recv_exact(sock, length)


def send_packet(sock, sequence, payload):
    length = len(payload)
    if length > MAX_PACKET:
        raise ValueError("outgoing MySQL packet exceeds the configured limit")
    header = bytes((length & 0xff, (length >> 8) & 0xff,
                    (length >> 16) & 0xff, sequence & 0xff))
    sock.sendall(header + payload)


def nul_string(data, offset):
    end = data.find(b"\x00", offset)
    if end < 0:
        return None, offset
    return data[offset:end].decode("utf-8", "replace"), end + 1


def parse_greeting(payload):
    result = {"raw_hex": payload.hex(), "protocol_version": None,
              "server_version": None}
    if not payload:
        return result
    result["protocol_version"] = payload[0]
    if payload[0] == 10:
        result["server_version"], _ = nul_string(payload, 1)
    return result


def response_summary(payload):
    summary = {"raw_hex": payload.hex(), "first_byte": payload[0] if payload else None}
    if not payload:
        summary["kind"] = "empty_response"
    elif payload[0] == 0x00:
        summary["kind"] = "OK"
    elif payload[0] == 0xff:
        summary["kind"] = "ERR"
        if len(payload) >= 3:
            summary["error_code"] = struct.unpack("<H", payload[1:3])[0]
        if len(payload) >= 9 and payload[3:4] == b"#":
            summary["sqlstate"] = payload[4:9].decode("ascii", "replace")
            summary["message"] = payload[9:].decode("utf-8", "replace")
        elif len(payload) > 3:
            summary["message"] = payload[3:].decode("utf-8", "replace")
    elif payload[0] == 0xfe:
        summary["kind"] = "authentication_switch_or_eof"
    else:
        summary["kind"] = "other_protocol_response"
    return summary


def main():
    evidence = {
        "target": f"{HOST}:{PORT}",
        "method": "MySQL classic protocol handshake with empty username and empty authentication response",
        "credentials_supplied": False,
        "default_credential_examples_repeated": False,
        "session_established": False,
        "coverage_note": "Tests only an empty-identity protocol handshake; a denial or incomplete exchange says nothing about other authentication paths."
    }
    try:
        with socket.create_connection((HOST, PORT), timeout=TIMEOUT) as sock:
            sock.settimeout(TIMEOUT)
            seq, greeting = read_packet(sock)
            evidence["greeting_sequence"] = seq
            evidence["greeting"] = parse_greeting(greeting)
            if not greeting or greeting[0] != 10:
                evidence["result"] = "inconclusive_unrecognized_or_incomplete_greeting"
                print(json.dumps(evidence, sort_keys=True))
                return

            # CLIENT_PROTOCOL_41 | CLIENT_SECURE_CONNECTION. No database,
            # username, or authentication data is supplied.
            capabilities = 0x0200 | 0x8000
            response = (
                struct.pack("<I", capabilities)
                + struct.pack("<I", 1024 * 1024)
                + bytes([45])
                + bytes(23)
                + b"\x00"  # empty username
                + b"\x00"  # empty authentication response length
            )
            send_packet(sock, (seq + 1) & 0xff, response)

            auth_observations = []
            auth_seq, auth_payload = read_packet(sock)
            auth_observations.append({"sequence": auth_seq, **response_summary(auth_payload)})

            # Handle one server-requested plugin switch with an empty response;
            # no authentication material is introduced.
            if auth_payload[:1] == b"\xfe" and len(auth_payload) > 1:
                send_packet(sock, (auth_seq + 1) & 0xff, b"")
                auth_seq, auth_payload = read_packet(sock)
                auth_observations.append({"sequence": auth_seq, **response_summary(auth_payload)})

            evidence["authentication_responses"] = auth_observations
            if auth_payload[:1] == b"\x00":
                evidence["session_established"] = True
                evidence["result"] = "confirmed_unauthenticated_session"
                query = b"\x03SELECT CURRENT_USER(), USER(), DATABASE()"
                send_packet(sock, (auth_seq + 1) & 0xff, query)
                query_seq, query_payload = read_packet(sock)
                evidence["read_only_identity_query"] = {
                    "query": "SELECT CURRENT_USER(), USER(), DATABASE()",
                    "response_sequence": query_seq,
                    **response_summary(query_payload)
                }
            elif auth_payload[:1] == b"\xff":
                evidence["result"] = "denied"
            else:
                evidence["result"] = "incomplete_or_inconclusive_protocol_exchange"

    except (OSError, EOFError, ValueError, struct.error) as exc:
        evidence["result"] = "incomplete_or_inconclusive_protocol_exchange"
        evidence["error"] = f"{type(exc).__name__}: {exc}"
    except Exception as exc:
        evidence["result"] = "incomplete_or_inconclusive_protocol_exchange"
        evidence["error"] = f"unexpected {type(exc).__name__}: {exc}"

    print(json.dumps(evidence, sort_keys=True))


if __name__ == "__main__":
    main()

