import json
import socket
import time

HOST = "192.168.2.254"
PORT = 33060
TIMEOUT_SECONDS = 5.0
MAX_FRAME_LENGTH = 65536

received = bytearray()
result = {
    "target": {"host": HOST, "port": PORT},
    "connection": "not_attempted",
    "data_sent": False,
    "received_hex": "",
    "received_length": 0,
    "frame": None,
    "parser_status": "not_run",
    "interpretation": "",
    "limitations": [],
}


def receive_exact(sock, count):
    """Read up to count bytes, retaining any partial data on timeout or EOF."""
    chunk = bytearray()
    while len(chunk) < count:
        try:
            part = sock.recv(count - len(chunk))
        except socket.timeout:
            return bytes(chunk), "timeout"
        if not part:
            return bytes(chunk), "eof"
        chunk.extend(part)
        received.extend(part)
    return bytes(chunk), "complete"


started = time.monotonic()
try:
    with socket.create_connection((HOST, PORT), timeout=TIMEOUT_SECONDS) as sock:
        result["connection"] = "connected"
        sock.settimeout(TIMEOUT_SECONDS)
        header, header_status = receive_exact(sock, 4)
        if len(header) < 4:
            result["parser_status"] = "incomplete_header"
            result["limitations"].append(
                "The first four bytes of a length-prefixed frame were not fully received."
            )
            result["read_status"] = header_status
        else:
            declared_length = int.from_bytes(header, "little")
            result["frame"] = {"declared_length": declared_length, "length_field_bytes": 4}
            if declared_length < 1:
                result["parser_status"] = "invalid_frame_length"
                result["limitations"].append(
                    "The declared frame length does not include a message type byte."
                )
            elif declared_length > MAX_FRAME_LENGTH:
                result["parser_status"] = "frame_exceeds_read_limit"
                result["limitations"].append(
                    "The declared first frame exceeds the 65536-byte read limit; its body was not read."
                )
            else:
                body, body_status = receive_exact(sock, declared_length)
                if body:
                    message_type = body[0]
                    result["frame"]["message_type"] = message_type
                    result["frame"]["payload_length_received"] = max(0, len(body) - 1)
                if len(body) != declared_length:
                    result["parser_status"] = "incomplete_frame"
                    result["read_status"] = body_status
                    result["limitations"].append(
                        "The first frame body was not fully received; interpretation is limited to received bytes."
                    )
                else:
                    result["parser_status"] = "length_prefixed_frame_parsed"
                    if body[0] == 11:
                        result["interpretation"] = (
                            "Message type 11 is consistent with the MySQL X Protocol NOTICE message type; "
                            "this single frame does not definitively identify the service or expose authentication state."
                        )
                    else:
                        result["interpretation"] = (
                            "A complete length-prefixed frame was received, but its message type alone is not "
                            "sufficient to identify the service definitively."
                        )
except (OSError, socket.timeout) as exc:
    if result["connection"] == "not_attempted":
        result["connection"] = "failed"
    else:
        result["connection"] = "connected_read_failed"
    result["parser_status"] = "not_parsed_or_incomplete"
    result["error"] = {"type": type(exc).__name__, "message": str(exc)}
    result["limitations"].append("No credentials or protocol request were sent.")
finally:
    result["elapsed_seconds"] = round(time.monotonic() - started, 3)
    result["received_hex"] = received.hex()
    result["received_length"] = len(received)
    if not result["interpretation"]:
        result["interpretation"] = "No complete first protocol frame was confidently interpreted."
    print(json.dumps(result, sort_keys=True))

