import json
import socket
import struct

HOST = "192.168.2.254"
PORT = 33060
TIMEOUT_SECONDS = 3.0
MAX_FRAME_BYTES = 1024 * 1024
MAX_FRAMES = 16

# MySQL X frame length includes the one-byte message type. Message type 1 is
# CON_CAPABILITIES_GET; its protobuf message has no fields.
REQUEST = struct.pack("<I", 1) + b"\x01"


def read_varint(data, pos):
    value = 0
    shift = 0
    while pos < len(data) and shift < 70:
        byte = data[pos]
        pos += 1
        value |= (byte & 0x7f) << shift
        if not byte & 0x80:
            return value, pos
        shift += 7
    raise ValueError("truncated or oversized protobuf varint")


def protobuf_fields(data):
    """Return protobuf fields as (field_number, wire_type, value)."""
    fields = []
    pos = 0
    while pos < len(data):
        key, pos = read_varint(data, pos)
        number, wire = key >> 3, key & 7
        if number == 0:
            raise ValueError("protobuf field number zero")
        if wire == 0:
            value, pos = read_varint(data, pos)
        elif wire == 1:
            if pos + 8 > len(data):
                raise ValueError("truncated fixed64 protobuf field")
            value = data[pos:pos + 8]
            pos += 8
        elif wire == 2:
            length, pos = read_varint(data, pos)
            if length > len(data) - pos:
                raise ValueError("truncated length-delimited protobuf field")
            value = data[pos:pos + length]
            pos += length
        elif wire == 5:
            if pos + 4 > len(data):
                raise ValueError("truncated fixed32 protobuf field")
            value = data[pos:pos + 4]
            pos += 4
        else:
            raise ValueError("unsupported protobuf wire type %d" % wire)
        fields.append((number, wire, value))
    return fields


def parse_any(raw):
    """Decode the documented top-level Mysqlx.Datatypes.Any fields."""
    result = {"raw_hex": raw.hex(), "fields": []}
    try:
        for number, wire, value in protobuf_fields(raw):
            item = {"field_number": number, "wire_type": wire}
            if wire == 0:
                item["value"] = value
            elif wire == 2:
                item["raw_hex"] = value.hex()
                if number == 2:
                    try:
                        item["scalar"] = parse_scalar(value)
                    except ValueError as exc:
                        item["scalar_parse_error"] = str(exc)
                elif number in (3, 4):
                    item["nested_fields"] = describe_fields(value)
                else:
                    item["utf8"] = safe_utf8(value)
            else:
                item["raw_hex"] = value.hex()
            result["fields"].append(item)
        types = [v for n, w, v in protobuf_fields(raw) if n == 1 and w == 0]
        if types:
            result["any_type"] = types[0]
    except ValueError as exc:
        result["parse_error"] = str(exc)
    return result


def safe_utf8(value):
    try:
        text = value.decode("utf-8")
    except UnicodeDecodeError:
        return None
    if all(ch.isprintable() or ch in "\r\n\t" for ch in text):
        return text
    return None


def describe_fields(raw):
    fields = []
    for number, wire, value in protobuf_fields(raw):
        item = {"field_number": number, "wire_type": wire}
        if wire == 0:
            item["value"] = value
        else:
            item["raw_hex"] = value.hex()
            if wire == 2:
                decoded = safe_utf8(value)
                if decoded is not None:
                    item["utf8"] = decoded
        fields.append(item)
    return fields


def parse_scalar(raw):
    result = {"raw_hex": raw.hex(), "fields": []}
    for number, wire, value in protobuf_fields(raw):
        item = {"field_number": number, "wire_type": wire}
        if wire == 0:
            item["value"] = value
        else:
            item["raw_hex"] = value.hex()
            if wire == 2:
                if number == 7:  # Scalar.v_octets (Mysqlx.Datatypes.Octets)
                    try:
                        octet_fields = protobuf_fields(value)
                        item["octets_fields"] = describe_fields(value)
                        for octet_number, octet_wire, octet_value in octet_fields:
                            if octet_number == 1 and octet_wire == 2:
                                item["octets_value_hex"] = octet_value.hex()
                                item["octets_value_utf8"] = safe_utf8(octet_value)
                    except ValueError as exc:
                        item["octets_parse_error"] = str(exc)
                else:
                    item["utf8"] = safe_utf8(value)
        result["fields"].append(item)
    return result


def parse_capabilities(payload):
    decoded = {"capabilities": [], "protobuf_parse_error": None}
    try:
        top_fields = protobuf_fields(payload)
        for number, wire, raw in top_fields:
            if number != 1 or wire != 2:
                continue
            entry = {"raw_hex": raw.hex()}
            try:
                cap_fields = protobuf_fields(raw)
                names = [v for n, w, v in cap_fields if n == 1 and w == 2]
                values = [v for n, w, v in cap_fields if n == 2 and w == 2]
                if names:
                    entry["name"] = safe_utf8(names[0])
                    if entry["name"] is None:
                        entry["name_hex"] = names[0].hex()
                else:
                    entry["name"] = None
                if values:
                    entry["value"] = parse_any(values[0])
                else:
                    entry["value"] = None
                entry["unrecognized_or_extra_fields"] = [
                    {"field_number": n, "wire_type": w,
                     "value": v if w == 0 else v.hex()}
                    for n, w, v in cap_fields if (n, w) not in ((1, 2), (2, 2))
                ]
            except ValueError as exc:
                entry["capability_parse_error"] = str(exc)
            decoded["capabilities"].append(entry)
    except ValueError as exc:
        decoded["protobuf_parse_error"] = str(exc)
    return decoded


def recv_exact(sock, count):
    chunks = []
    remaining = count
    while remaining:
        chunk = sock.recv(remaining)
        if not chunk:
            return b"".join(chunks), "peer closed before requested bytes arrived"
        chunks.append(chunk)
        remaining -= len(chunk)
    return b"".join(chunks), None


def main():
    result = {
        "target": "%s:%d" % (HOST, PORT),
        "request": {
            "description": "MySQL X CON_CAPABILITIES_GET, empty protobuf payload",
            "frame_hex": REQUEST.hex(),
            "length_prefix_little_endian": 1,
            "message_type": 1,
            "authentication_data_sent": False
        },
        "connection": "not_attempted",
        "response_frames": [],
        "limitations": [],
        "interpretation": (
            "No authentication messages or credentials are sent. Absence of advertised "
            "authentication metadata does not establish that authentication is unnecessary."
        )
    }
    try:
        with socket.create_connection((HOST, PORT), timeout=TIMEOUT_SECONDS) as sock:
            result["connection"] = "connected"
            sock.settimeout(TIMEOUT_SECONDS)
            sock.sendall(REQUEST)
            result["request"]["sent"] = True
            for index in range(MAX_FRAMES):
                try:
                    header, error = recv_exact(sock, 4)
                except socket.timeout:
                    result["limitations"].append("timed out waiting for the next response frame")
                    break
                if error:
                    if header:
                        result["limitations"].append("partial frame header captured: " + header.hex())
                    else:
                        result["limitations"].append("peer closed while awaiting another frame")
                    break
                length = struct.unpack("<I", header)[0]
                frame = {"index": index, "length_prefix_hex": header.hex(), "declared_length": length}
                if length < 1:
                    frame["framing_error"] = "frame length excludes required message-type byte"
                    result["response_frames"].append(frame)
                    break
                if length > MAX_FRAME_BYTES:
                    frame["framing_error"] = "declared frame exceeds local capture limit"
                    result["response_frames"].append(frame)
                    result["limitations"].append("frame body not read due to capture limit")
                    break
                try:
                    body, error = recv_exact(sock, length)
                except socket.timeout:
                    body, error = b"", "timed out before frame body completed"
                frame["captured_body_hex"] = body.hex()
                frame["captured_body_length"] = len(body)
                if body:
                    frame["message_type"] = body[0]
                    frame["payload_hex"] = body[1:].hex()
                    if len(body) == length:
                        frame["complete"] = True
                        if body[0] == 2:
                            frame["capabilities_decoding"] = parse_capabilities(body[1:])
                    else:
                        frame["complete"] = False
                else:
                    frame["complete"] = False
                result["response_frames"].append(frame)
                if error:
                    result["limitations"].append(error)
                    break
            else:
                result["limitations"].append("stopped after maximum frame count")
    except socket.timeout as exc:
        result["connection"] = "timeout"
        result["error"] = str(exc)
    except OSError as exc:
        result["connection"] = "error"
        result["error"] = "%s: %s" % (type(exc).__name__, exc)
    print(json.dumps(result, sort_keys=True))


if __name__ == "__main__":
    main()

