import hashlib
import json
import sys
from html.parser import HTMLParser
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen
from urllib.parse import urljoin

URL = "http://192.168.2.4/login.php"


class FormParser(HTMLParser):
    def __init__(self, document_url):
        super().__init__(convert_charrefs=True)
        self.document_url = document_url
        self.forms = []
        self.active_form = None
        self.select_stack = []
        self.textarea = None
        self.option = None

    def _attrs(self, attrs):
        return {key.lower(): (value if value is not None else "") for key, value in attrs}

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        a = self._attrs(attrs)
        if tag == "form":
            form = {
                "id": len(self.forms),
                "method": (a.get("method") or "get").strip().upper(),
                "raw_action": a.get("action", ""),
                "action": urljoin(self.document_url, a.get("action", "")),
                "enctype": a.get("enctype", "application/x-www-form-urlencoded"),
                "controls": [],
            }
            self.forms.append(form)
            self.active_form = form
        elif tag == "input":
            self._add_control({
                "tag": "input",
                "type": (a.get("type") or "text").lower(),
                "name": a.get("name", ""),
                "value": a.get("value", ""),
                "id": a.get("id", ""),
                "required": "required" in a,
                "disabled": "disabled" in a,
                "checked": "checked" in a,
                "form": a.get("form", ""),
            })
        elif tag == "button":
            control = {
                "tag": "button",
                "type": (a.get("type") or "submit").lower(),
                "name": a.get("name", ""),
                "value": a.get("value", ""),
                "id": a.get("id", ""),
                "required": "required" in a,
                "disabled": "disabled" in a,
                "form": a.get("form", ""),
                "text": "",
            }
            self._add_control(control)
            self.button = control
        elif tag == "select":
            control = {
                "tag": "select", "name": a.get("name", ""),
                "id": a.get("id", ""), "multiple": "multiple" in a,
                "required": "required" in a, "disabled": "disabled" in a,
                "form": a.get("form", ""), "options": [],
            }
            self._add_control(control)
            self.select_stack.append(control)
        elif tag == "option" and self.select_stack:
            self.option = {"value": a.get("value"), "selected": "selected" in a, "text": ""}
        elif tag == "textarea":
            self.textarea = {
                "tag": "textarea", "name": a.get("name", ""),
                "id": a.get("id", ""), "required": "required" in a,
                "disabled": "disabled" in a, "form": a.get("form", ""),
                "value": "",
            }

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        self.handle_endtag(tag)

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag == "form":
            self.active_form = None
        elif tag == "option" and self.option is not None:
            if self.select_stack:
                self.select_stack[-1]["options"].append(self.option)
            self.option = None
        elif tag == "select" and self.select_stack:
            self.select_stack.pop()
        elif tag == "textarea" and self.textarea is not None:
            self._add_control(self.textarea)
            self.textarea = None
        elif tag == "button":
            self.button = None

    def handle_data(self, data):
        if self.option is not None:
            self.option["text"] += data
        if self.textarea is not None:
            self.textarea["value"] += data
        button = getattr(self, "button", None)
        if button is not None:
            button["text"] += data

    def _add_control(self, control):
        if self.active_form is not None:
            control["form_id"] = self.active_form["id"]
            self.active_form["controls"].append(control)
        else:
            control["form_id"] = None


def main():
    result = {"requested_url": URL}
    request = Request(URL, headers={"User-Agent": "form-inspection/1.0", "Accept": "text/html,*/*;q=0.8"}, method="GET")
    try:
        try:
            response = urlopen(request, timeout=15)
        except HTTPError as exc:
            response = exc
        with response:
            raw = response.read()
            status = response.getcode()
            headers = list(response.headers.items())
            final_url = response.geturl()
        content_type = next((v for k, v in headers if k.lower() == "content-type"), "")
        charset = "utf-8"
        for part in content_type.split(";")[1:]:
            part = part.strip()
            if part.lower().startswith("charset="):
                charset = part.split("=", 1)[1].strip(" \"'") or "utf-8"
                break
        try:
            body = raw.decode(charset, errors="replace")
            decode_status = "decoded using declared charset" if "charset=" in content_type.lower() else "decoded as UTF-8 (no charset declared)"
        except LookupError:
            body = raw.decode("utf-8", errors="replace")
            decode_status = "declared charset was unknown; decoded as UTF-8 with replacement"
        result.update({
            "http_status": status,
            "response_headers": headers,
            "final_url": final_url,
            "body_bytes": len(raw),
            "body_sha256": hashlib.sha256(raw).hexdigest(),
            "decode_status": decode_status,
            "response_body": body,
        })
        parser = FormParser(final_url)
        try:
            parser.feed(body)
            parser.close()
            result["parse_status"] = "completed"
            result["forms"] = parser.forms
            result["form_count"] = len(parser.forms)
        except Exception as exc:
            result["parse_status"] = "failed"
            result["parse_error"] = repr(exc)
            result["forms"] = parser.forms
            result["form_count"] = len(parser.forms)
    except (URLError, TimeoutError, OSError) as exc:
        result.update({"request_status": "failed", "error": repr(exc)})
    except Exception as exc:
        result.update({"request_status": "failed", "error": repr(exc)})
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

