import hashlib
import json
import re
import sys
from html.parser import HTMLParser
from http.cookiejar import CookieJar
from urllib.error import HTTPError, URLError
from urllib.parse import urljoin, urlsplit, urlunsplit
from urllib.request import HTTPRedirectHandler, HTTPCookieProcessor, Request, build_opener

BASE = "http://192.168.2.4/login.php"
ORIGIN = ("http", "192.168.2.4", 80)
TIMEOUT = 15


class PageParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.forms = []
        self.links = []
        self.text_parts = []
        self.current_form = None
        self.current_anchor = None
        self.skip_text = 0
        self.title_parts = []
        self.in_title = False
        self._select = None
        self._option = None

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if tag in ("script", "style"):
            self.skip_text += 1
        if tag == "title":
            self.in_title = True
        if tag == "form":
            self.current_form = {"method": (a.get("method") or "GET").upper(), "raw_action": a.get("action", ""), "controls": []}
            self.forms.append(self.current_form)
        elif tag == "a":
            self.current_anchor = {"href": a.get("href", ""), "text_parts": []}
        elif tag == "select":
            self._select = {"name": a.get("name", ""), "disabled": "disabled" in a, "options": []}
        elif tag == "option" and self._select is not None:
            self._option = {"value": a.get("value"), "selected": "selected" in a, "text": []}
        elif tag == "input" and self.current_form is not None:
            typ = (a.get("type") or "text").lower()
            self.current_form["controls"].append({"tag": "input", "type": typ, "name": a.get("name", ""), "value": a.get("value", ""), "disabled": "disabled" in a, "checked": "checked" in a})
        elif tag == "textarea" and self.current_form is not None:
            self.current_form["controls"].append({"tag": "textarea", "name": a.get("name", ""), "value": "", "disabled": "disabled" in a, "_text": []})
        elif tag == "button" and self.current_form is not None:
            self.current_form["controls"].append({"tag": "button", "type": (a.get("type") or "submit").lower(), "name": a.get("name", ""), "value": a.get("value", ""), "disabled": "disabled" in a})

    def handle_endtag(self, tag):
        if tag in ("script", "style") and self.skip_text:
            self.skip_text -= 1
        if tag == "title":
            self.in_title = False
        if tag == "a" and self.current_anchor is not None:
            self.current_anchor["text"] = " ".join(" ".join(self.current_anchor.pop("text_parts")).split())
            self.links.append(self.current_anchor)
            self.current_anchor = None
        if tag == "option" and self._select is not None and self._option is not None:
            self._option["text"] = " ".join(self._option.pop("text")).strip()
            self._select["options"].append(self._option)
            self._option = None
        if tag == "select" and self._select is not None:
            selected = [o for o in self._select["options"] if o["selected"]]
            if not selected and self._select["options"]:
                selected = self._select["options"][:1]
            if self.current_form is not None and self._select["name"] and not self._select["disabled"]:
                for o in selected:
                    self.current_form["controls"].append({"tag": "select", "name": self._select["name"], "value": o["value"] if o["value"] is not None else o["text"], "disabled": False})
            self._select = None
        if tag == "textarea" and self.current_form is not None:
            for c in reversed(self.current_form["controls"]):
                if c["tag"] == "textarea" and "_text" in c:
                    c["value"] = "".join(c.pop("_text"))
                    break
        if tag == "form":
            self.current_form = None

    def handle_data(self, data):
        if self.in_title:
            self.title_parts.append(data)
        if not self.skip_text:
            self.text_parts.append(data)
        if self.current_anchor is not None:
            self.current_anchor["text_parts"].append(data)
        if self._option is not None:
            self._option["text"].append(data)
        if self.current_form is not None:
            for c in reversed(self.current_form["controls"]):
                if c["tag"] == "textarea" and "_text" in c:
                    c["_text"].append(data)
                    break


class RecordingRedirectHandler(HTTPRedirectHandler):
    def __init__(self):
        self.events = []

    def redirect_request(self, req, fp, code, msg, headers, newurl):
        self.events.append({"status": code, "from": req.full_url, "location": newurl})
        return super().redirect_request(req, fp, code, msg, headers, newurl)


def same_origin(url):
    p = urlsplit(url)
    port = p.port or (443 if p.scheme == "https" else 80)
    return (p.scheme, p.hostname, port) == ORIGIN


def cookie_names(jar):
    return sorted({c.name for c in jar})


def fetch(opener, redirects, url, method="GET", data=None):
    before = len(redirects.events)
    req = Request(url, data=data, method=method, headers={"User-Agent": "Mozilla/5.0", "Accept": "text/html,*/*;q=0.8"})
    try:
        with opener.open(req, timeout=TIMEOUT) as response:
            raw = response.read()
            headers = list(response.headers.items())
            result = {"requested_url": url, "method": method, "status": response.status, "final_url": response.geturl(), "headers": headers, "body": raw, "error": ""}
    except HTTPError as e:
        raw = e.read()
        result = {"requested_url": url, "method": method, "status": e.code, "final_url": e.geturl(), "headers": list(e.headers.items()), "body": raw, "error": "HTTPError"}
    except (URLError, OSError, TimeoutError) as e:
        result = {"requested_url": url, "method": method, "status": None, "final_url": None, "headers": [], "body": b"", "error": str(e)}
    result["redirects"] = redirects.events[before:]
    return result


def page_record(response, jar):
    raw = response["body"]
    content_type = next((v for k, v in response["headers"] if k.lower() == "content-type"), "")
    charset = "utf-8"
    m = re.search(r"charset\s*=\s*['\"]?([\w.-]+)", content_type, re.I)
    if m:
        charset = m.group(1)
    try:
        html = raw.decode(charset, errors="replace")
        decode_status = "decoded as " + charset
    except LookupError:
        html = raw.decode("utf-8", errors="replace")
        decode_status = "unknown declared charset; decoded as utf-8 with replacement"
    parser = PageParser()
    try:
        parser.feed(html)
        parser.close()
        parse_status = "completed"
    except Exception as e:
        parse_status = "failed: " + repr(e)
    visible = " ".join(" ".join(parser.text_parts).split())
    return {
        "requested_url": response["requested_url"], "method": response["method"],
        "status": response["status"], "final_url": response["final_url"],
        "redirects": response["redirects"], "error": response["error"],
        "body_bytes": len(raw), "body_sha256": hashlib.sha256(raw).hexdigest(),
        "decode_status": decode_status, "parse_status": parse_status,
        "title": " ".join(parser.title_parts).strip(), "page_text": visible,
        "forms": parser.forms, "links": parser.links,
        "cookie_names_after_response": cookie_names(jar),
        "set_cookie_names": sorted({part.split("=", 1)[0].strip() for k, v in response["headers"] if k.lower() == "set-cookie" for part in [v.split(";", 1)[0]] if "=" in part})
    }, parser


def relevant_link(link):
    target = (link.get("href", "") + " " + link.get("text", "")).lower()
    return bool(re.search(r"admin|flag|dashboard|student|account|profile|secret", target)) and not bool(re.search(r"logout|sign.?out", target))


def main():
    jar = CookieJar()
    redirects = RecordingRedirectHandler()
    opener = build_opener(HTTPCookieProcessor(jar), redirects)
    output = {"target": BASE, "credential_source": "already observed task evidence", "credentials_submitted": {"username": "student", "password": "student"}, "pages": [], "route_followup": [], "limitations": []}

    initial = fetch(opener, redirects, BASE)
    initial_record, initial_parser = page_record(initial, jar)
    output["initial_get"] = initial_record
    if initial["status"] != 200 or not initial_parser.forms:
        output["limitations"].append("Could not obtain a successful response containing a parseable form; no credential submission was made.")
        print(json.dumps(output, ensure_ascii=False))
        return

    form = initial_parser.forms[0]
    action = urljoin(initial["final_url"] or BASE, form.get("raw_action", ""))
    method = (form.get("method") or "GET").upper()
    output["submitted_form"] = {"method": method, "raw_action": form.get("raw_action", ""), "resolved_action": action, "control_names": [c.get("name", "") for c in form["controls"]]}
    if not same_origin(action):
        output["limitations"].append("The observed form action is not same-origin; credentials were not sent to it.")
        print(json.dumps(output, ensure_ascii=False))
        return
    fields = []
    for c in form["controls"]:
        name = c.get("name", "")
        typ = c.get("type", "text").lower()
        if not name or c.get("disabled") or typ in ("submit", "button", "reset", "image", "file"):
            continue
        if typ in ("checkbox", "radio") and not c.get("checked"):
            continue
        val = c.get("value", "")
        if name == "username":
            val = "student"
        elif name == "password":
            val = "student"
        fields.append((name, val))
    names = {name for name, _ in fields}
    if "username" not in names:
        fields.append(("username", "student"))
    if "password" not in names:
        fields.append(("password", "student"))
    payload = None
    if method == "POST":
        from urllib.parse import urlencode
        payload = urlencode(fields).encode("ascii")
    elif method == "GET":
        from urllib.parse import urlencode
        parts = urlsplit(action)
        query = "&".join(x for x in (parts.query, urlencode(fields)) if x)
        action = urlunsplit((parts.scheme, parts.netloc, parts.path, query, parts.fragment))
    else:
        output["limitations"].append("The observed form method is not GET or POST; no unsupported method was attempted.")
        print(json.dumps(output, ensure_ascii=False))
        return

    submitted = fetch(opener, redirects, action, method=method, data=payload)
    submitted_record, submitted_parser = page_record(submitted, jar)
    output["submission"] = submitted_record
    output["cookie_names_after_submission"] = cookie_names(jar)
    output["pages"].append(submitted_record)

    # Follow only relevant routes actually exposed as links by returned student-facing pages.
    queue = []
    def enqueue_links(record, parser):
        for link in parser.links:
            if not link.get("href") or not relevant_link(link):
                continue
            resolved = urljoin(record.get("final_url") or BASE, link["href"])
            p = urlsplit(resolved)
            if same_origin(resolved) and p.scheme in ("http", "https"):
                canonical = urlunsplit((p.scheme, p.netloc, p.path or "/", p.query, ""))
                queue.append((canonical, link.get("text", ""), record.get("final_url")))
    enqueue_links(submitted_record, submitted_parser)
    seen = set()
    while queue:
        url, label, source = queue.pop(0)
        if url in seen:
            continue
        seen.add(url)
        response = fetch(opener, redirects, url)
        record, parser = page_record(response, jar)
        output["route_followup"].append({"exposed_by": source, "link_text": label, "result": record})
        if response["status"] is not None and parser is not None:
            enqueue_links(record, parser)
    if not output["route_followup"]:
        output["limitations"].append("The resulting page exposed no relevant same-origin links matching the route criteria; unlinked routes were not enumerated.")
    print(json.dumps(output, ensure_ascii=False))


if __name__ == "__main__":
    main()

