import json
import re
from urllib.parse import urljoin, urlsplit

import framework_evidence

BASE = "http://192.168.2.4:80"
INITIAL = [
    ("/robots.txt", "route-discovery metadata"),
    ("/sitemap.xml", "route-discovery metadata"),
    ("/", "observed service root"),
    ("/login.php", "previously observed login route"),
    ("/admin.php", "previously observed admin route"),
]
# Explicit conventional-path discovery candidates; GET only, no form submissions.
WORDLIST = [
    "/admin", "/administrator", "/dashboard", "/index.php", "/home.php",
    "/flag", "/flag.php", "/secret", "/secret.php", "/api", "/api/",
    "/api.php", "/user.php", "/profile.php", "/config.php", "/backup",
    "/uploads/", "/private/", "/server-status", "/.well-known/",
]


def response_text(envelope):
    if not isinstance(envelope, dict):
        return ""
    value = envelope.get("stdout", "")
    return value if isinstance(value, str) else ""


def referenced_paths(text):
    """Extract same-origin URL references and absolute route-like paths."""
    found = set()
    for value in re.findall(
        r'''(?:href|src|action)\s*=\s*["']([^"']+)["']''', text, re.I
    ):
        absolute = urljoin(BASE + "/", value)
        parsed = urlsplit(absolute)
        if parsed.scheme in ("http", "https") and parsed.netloc == "192.168.2.4:80":
            if parsed.path.startswith("/"):
                found.add(parsed.path)
    for value in re.findall(r'''(?<![A-Za-z0-9:])(/[A-Za-z0-9_./%-]+)''', text):
        path = value.split("#", 1)[0]
        if path.startswith("//"):
            continue
        if path and not path.startswith("/../"):
            found.add(path)
    return found


queue = []
sources = {}
for path, source in INITIAL:
    if path not in sources:
        queue.append(path)
        sources[path] = [source]
for path in WORDLIST:
    if path not in sources:
        queue.append(path)
        sources[path] = ["explicit conventional-path candidate list"]
    else:
        sources[path].append("explicit conventional-path candidate list")

results = []
examined = set()
while queue:
    path = queue.pop(0)
    if path in examined:
        continue
    examined.add(path)
    url = BASE + path
    record = {"url": url, "discovery_sources": sources.get(path, [])}
    try:
        envelope = framework_evidence.run_tool([
            "curl", "-sS", "-i", "--max-time", "10", "--max-redirs", "0", url
        ])
        record["tool_result"] = envelope
        text = response_text(envelope)
        new_paths = sorted(referenced_paths(text) - examined - set(sources))
        record["same_origin_paths_referenced"] = new_paths
        for discovered in new_paths:
            sources.setdefault(discovered, []).append("reference found in response to " + path)
            queue.append(discovered)
    except Exception as exc:
        record["execution_error"] = repr(exc)
        record["same_origin_paths_referenced"] = []
    results.append(record)

print(json.dumps({
    "target": BASE,
    "method": "GET-only metadata retrieval, response-reference extraction, and explicit conventional-path probing",
    "credentials_or_form_submissions": "none",
    "request_count": len(results),
    "paths_examined": [item["url"] for item in results],
    "results": results,
    "coverage_note": "Only the recorded candidate paths and same-origin references extracted from their responses were examined. This coverage does not establish that other paths are unavailable.",
}, ensure_ascii=False))

