import json
from pathlib import Path

ARTIFACT = "4d561dc7a6859c7e1bd8e0e9a869c88dbbe82d272fceaccb4ae9e1bd27066fa7.json"
REPORT_REF = "b593cf9646786452ef1492b37dc93a2772e88c214044ef5a3aa0b0ba2fb9f689"
DISCOVERY_NODE = "r5__node-discover_unlinked_http_paths__d1__discover_http_paths"

candidates = [
    Path("llm_inputs") / ARTIFACT,
    Path.cwd() / "llm_inputs" / ARTIFACT,
    Path("/root/llm_inputs") / ARTIFACT,
    Path("/root/scripts/../llm_inputs") / ARTIFACT,
]
seen = set()
artifact_path = None
for candidate in candidates:
    try:
        resolved = candidate.resolve()
    except OSError:
        continue
    if resolved in seen:
        continue
    seen.add(resolved)
    if resolved.is_file():
        artifact_path = resolved
        break

if artifact_path is None:
    print(json.dumps({
        "retrieval_status": "unavailable",
        "report_reference": REPORT_REF,
        "archive_artifact": ARTIFACT,
        "examined_locations": [str(p) for p in sorted(seen)],
        "limitation": "The supplied archived original-input artifact was not present at the checked exact paths; the report contents could not be retrieved. No conclusion about omitted response records is justified."
    }, ensure_ascii=False))
    raise SystemExit(0)

try:
    with artifact_path.open("r", encoding="utf-8") as handle:
        document = json.load(handle)
except Exception as exc:
    print(json.dumps({
        "retrieval_status": "unavailable",
        "report_reference": REPORT_REF,
        "archive_artifact": str(artifact_path),
        "limitation": "The archived file was found but could not be parsed as JSON.",
        "error": type(exc).__name__ + ": " + str(exc)
    }, ensure_ascii=False))
    raise SystemExit(0)

ref_matches = []
discovery_matches = []

def walk(value):
    if isinstance(value, dict):
        try:
            serialized = json.dumps(value, ensure_ascii=False)
        except (TypeError, ValueError):
            serialized = ""
        if REPORT_REF in serialized:
            ref_matches.append(value)
        if value.get("node_id") == DISCOVERY_NODE:
            discovery_matches.append(value)
        for child in value.values():
            walk(child)
    elif isinstance(value, list):
        for child in value:
            walk(child)

walk(document)
# Avoid duplicating identical matches when an enclosing object and a nested object
# both contain the reference. Preserve every distinct matching object.
def unique_objects(items):
    result = []
    encoded = set()
    for item in items:
        key = json.dumps(item, sort_keys=True, ensure_ascii=False)
        if key not in encoded:
            encoded.add(key)
            result.append(item)
    return result

ref_matches = unique_objects(ref_matches)
discovery_matches = unique_objects(discovery_matches)

if ref_matches:
    status = "report_reference_found"
    limitation = ""
elif discovery_matches:
    status = "discovery_observation_found_reference_not_located"
    limitation = "The archived input contains the discovery observation but no object containing the requested report reference. Review the included observation for its actual report payload and any truncation; absence of the reference is not evidence about unlocated response records."
else:
    status = "report_not_located_in_archive"
    limitation = "The archived input was readable, but neither the requested report reference nor the identified discovery observation was found. This does not establish that the report or omitted responses do not exist."

print(json.dumps({
    "retrieval_status": status,
    "report_reference": REPORT_REF,
    "archive_artifact": str(artifact_path),
    "report_reference_matches": ref_matches,
    "discovery_observations": discovery_matches,
    "limitation": limitation
}, ensure_ascii=False))
